package com.setuppicker;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * The hiscores' boss icons, for setups named after a boss, made small enough for a row of the list. Used from
 * the client thread only, as the game's sprites are.
 */
@Singleton
class BossIcons
{
	private final SpriteManager spriteManager;
	// by setup name, so each name is matched once
	private final Map<String, Optional<HiscoreSkill>> bosses = new HashMap<>();
	// by sprite id
	private final Map<Integer, BufferedImage> icons = new HashMap<>();

	@Inject
	BossIcons(SpriteManager spriteManager)
	{
		this.spriteManager = spriteManager;
	}

	/**
	 * The icon of the boss a setup of this name is for, at most width by height, or null when it isn't for a
	 * boss or the game hasn't loaded the icon yet.
	 */
	BufferedImage get(String setupName, int width, int height)
	{
		final HiscoreSkill boss = bosses.computeIfAbsent(setupName, name -> Optional.ofNullable(BossMatcher.match(name)))
			.orElse(null);
		if (boss == null)
		{
			return null;
		}
		final BufferedImage cached = icons.get(boss.getSpriteId());
		if (cached != null)
		{
			return cached;
		}
		final BufferedImage sprite = spriteManager.getSprite(boss.getSpriteId(), 0);
		if (sprite == null)
		{
			return null;
		}
		final BufferedImage icon = fit(sprite, width, height);
		icons.put(boss.getSpriteId(), icon);
		return icon;
	}

	/**
	 * The image, shrunk if needed to fit width by height, keeping its shape. Averaged rather than picking pixels,
	 * as the icons are shrunk by uneven amounts.
	 */
	static BufferedImage fit(BufferedImage image, int width, int height)
	{
		final double scale = Math.min(1, Math.min((double) width / image.getWidth(), (double) height / image.getHeight()));
		if (scale == 1)
		{
			return image;
		}
		final int w = Math.max(1, (int) Math.round(image.getWidth() * scale));
		final int h = Math.max(1, (int) Math.round(image.getHeight() * scale));
		final BufferedImage fitted = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = fitted.createGraphics();
		g.drawImage(image.getScaledInstance(w, h, Image.SCALE_AREA_AVERAGING), 0, 0, null);
		g.dispose();
		return fitted;
	}
}

package com.setuppicker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * Works out which boss a setup is for from its name: "Vorkath (dhcb)", "kq", "CoX CM" or "zuk". A setup is
 * matched to a boss when its name has the boss's name in it, or one of the names players call it by.
 */
final class BossMatcher
{
	// Names shorter than this have to be a word of their own in the setup's name, so "nex" doesn't match "next".
	// Longer ones can be anywhere in it, run together with other words or not.
	private static final int MIN_INSIDE_WORD = 6;

	// What players call the bosses besides their names, by the name of the boss in HiscoreSkill. Kept as strings
	// so a boss that's renamed or dropped from the client is just left out.
	private static final Map<String, String[]> NICKNAMES = new HashMap<>();

	static
	{
		nicknames("ABYSSAL_SIRE", "sire");
		nicknames("ALCHEMICAL_HYDRA", "hydra", "alch hydra");
		nicknames("AMOXLIATL", "amox");
		nicknames("ARAXXOR", "araxx", "rax");
		nicknames("BARROWS_CHESTS", "barrows");
		nicknames("BRYOPHYTA", "bryo");
		nicknames("CALVARION", "calv", "calvar ion");
		nicknames("CERBERUS", "cerb");
		nicknames("CHAMBERS_OF_XERIC", "cox", "chambers", "olm", "raids 1");
		nicknames("CHAMBERS_OF_XERIC_CHALLENGE_MODE", "cox cm", "cm cox", "cm", "challenge mode");
		nicknames("CHAOS_ELEMENTAL", "chaos ele");
		nicknames("COMMANDER_ZILYANA", "zilyana", "zily", "sara");
		nicknames("CORPOREAL_BEAST", "corp");
		nicknames("CRAZY_ARCHAEOLOGIST", "crazy arch");
		nicknames("DAGANNOTH_REX", "rex", "dks", "dagannoth kings", "dag kings");
		nicknames("DAGANNOTH_PRIME", "prime");
		nicknames("DAGANNOTH_SUPREME", "supreme");
		nicknames("DERANGED_ARCHAEOLOGIST", "deranged arch");
		nicknames("DOOM_OF_MOKHAIOTL", "doom", "mokhaiotl");
		nicknames("DUKE_SUCELLUS", "duke");
		nicknames("GENERAL_GRAARDOR", "graardor", "bandos");
		nicknames("GIANT_MOLE", "mole");
		nicknames("GROTESQUE_GUARDIANS", "grotesque", "guardians", "ggs", "gargs");
		nicknames("KALPHITE_QUEEN", "kq", "kalphite");
		nicknames("KING_BLACK_DRAGON", "kbd");
		nicknames("KREEARRA", "kree", "arma");
		nicknames("KRIL_TSUTSAROTH", "kril", "zammy");
		nicknames("LUNAR_CHESTS", "moons", "perilous moons", "moons of peril");
		nicknames("NIGHTMARE", "nm");
		nicknames("PHOSANIS_NIGHTMARE", "pnm", "phosani");
		nicknames("PHANTOM_MUSPAH", "muspah");
		nicknames("SARACHNIS", "sarach");
		nicknames("SCURRIUS", "scurri");
		nicknames("SHELLBANE_GRYPHON", "gryphon", "shellbane");
		nicknames("SOL_HEREDIT", "sol", "colosseum", "colo", "fortis");
		nicknames("TEMPOROSS", "tempo");
		nicknames("THE_CORRUPTED_GAUNTLET", "cg", "corrupted", "corrupted gauntlet", "cgauntlet");
		nicknames("THE_HUEYCOATL", "huey");
		nicknames("THE_LEVIATHAN", "levi");
		nicknames("THE_ROYAL_TITANS", "titans", "royal titans");
		nicknames("THE_WHISPERER", "whisp");
		nicknames("THEATRE_OF_BLOOD", "tob", "theatre", "verzik", "raids 2");
		nicknames("THEATRE_OF_BLOOD_HARD_MODE", "tob hm", "hm tob", "hmt");
		nicknames("THERMONUCLEAR_SMOKE_DEVIL", "thermy", "thermo", "smoke devil");
		nicknames("TOMBS_OF_AMASCUT", "toa", "tombs", "wardens", "raids 3");
		nicknames("TOMBS_OF_AMASCUT_EXPERT", "toa expert", "expert toa");
		nicknames("TZKAL_ZUK", "zuk", "inferno");
		nicknames("TZTOK_JAD", "jad", "fight caves", "caves");
		nicknames("VARDORVIS", "vard");
		nicknames("VORKATH", "vork");
		nicknames("WINTERTODT", "todt", "wt");
		nicknames("ZULRAH", "zul", "zully");
	}

	private static final List<Phrase> PHRASES = phrases();

	private BossMatcher()
	{
	}

	private static void nicknames(String boss, String... names)
	{
		NICKNAMES.put(boss, names);
	}

	/**
	 * The boss a setup of this name is for, or null for none.
	 */
	static HiscoreSkill match(String setupName)
	{
		final String words = normalize(setupName);
		if (words.isEmpty())
		{
			return null;
		}
		final String padded = " " + words + " ";
		final String compact = words.replace(" ", "");
		HiscoreSkill best = null;
		int bestLength = 0;
		int bestAt = Integer.MAX_VALUE;
		for (Phrase phrase : PHRASES)
		{
			final int at = phrase.compact.length() >= MIN_INSIDE_WORD || padded.contains(" " + phrase.words + " ")
				? compact.indexOf(phrase.compact) : -1;
			if (at < 0)
			{
				continue;
			}
			// the longest name found is the most particular, so "phosani's nightmare" over "nightmare"; between
			// equals, the first in the setup's name
			final int length = phrase.compact.length();
			if (length > bestLength || (length == bestLength && at < bestAt))
			{
				best = phrase.boss;
				bestLength = length;
				bestAt = at;
			}
		}
		return best;
	}

	/**
	 * Lowercase words of letters and digits, one space apart. Apostrophes go, along with an "'s" after a word,
	 * so "Kree'Arra" is "kreearra" and "Phosani's" is "phosani", any other mark parts words, and so does going
	 * from letters to digits, so "Vorkath2" is "vorkath 2".
	 */
	static String normalize(String name)
	{
		final String lower = name.toLowerCase(Locale.ROOT)
			.replaceAll("['’]s\\b", "")
			.replaceAll("['’]", "")
			.replaceAll("(?<=[a-z])(?=[0-9])|(?<=[0-9])(?=[a-z])", " ")
			.replaceAll("[^a-z0-9]+", " ");
		return lower.trim();
	}

	private static List<Phrase> phrases()
	{
		final List<Phrase> phrases = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.BOSS)
			{
				continue;
			}
			final String name = normalize(skill.getName());
			phrases.add(new Phrase(skill, name));
			if (name.startsWith("the "))
			{
				phrases.add(new Phrase(skill, name.substring("the ".length())));
			}
			for (String nickname : NICKNAMES.getOrDefault(skill.name(), new String[0]))
			{
				phrases.add(new Phrase(skill, normalize(nickname)));
			}
		}
		return Collections.unmodifiableList(phrases);
	}

	private static final class Phrase
	{
		private final HiscoreSkill boss;
		private final String words;
		private final String compact;

		private Phrase(HiscoreSkill boss, String words)
		{
			this.boss = boss;
			this.words = words;
			this.compact = words.replace(" ", "");
		}
	}
}

package com.setuppicker;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Takes the keyboard away from the chatbox while the picker's search box has it.
 *
 * <p>The chatbox reads keys through its key listener. The core Key Remapping plugin only acts while that
 * listener is set (its "chatbox focused" check), so with it removed Key Remapping stands down too: it stops
 * turning W/A/S/D into arrow keys, and Enter no longer unlocks its "Press Enter to Chat" input when all it was
 * meant to do was pick a setup. The listener is put back as soon as the search box loses focus.
 *
 * <p>Client thread only.
 */
@Singleton
public class ChatboxKeyGuard
{
	private final Client client;
	private Object[] savedListener;

	@Inject
	ChatboxKeyGuard(Client client)
	{
		this.client = client;
	}

	/**
	 * @param searchFocused whether the picker currently wants the keyboard
	 */
	public void sync(boolean searchFocused)
	{
		if (searchFocused)
		{
			suspend();
		}
		else
		{
			restore();
		}
	}

	private void suspend()
	{
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (chatbox == null)
		{
			return;
		}
		// Also re-suspends if the game rebuilt the chatbox, and so set the listener again, while searching
		final Object[] listener = chatbox.getOnKeyListener();
		if (listener != null)
		{
			savedListener = listener;
			chatbox.setOnKeyListener((Object[]) null);
		}
	}

	public void restore()
	{
		if (savedListener == null)
		{
			return;
		}
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		// If the game has set a listener in the meantime, that one is current: leave it
		if (chatbox != null && chatbox.getOnKeyListener() == null)
		{
			chatbox.setOnKeyListener(savedListener);
		}
		savedListener = null;
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines the items in the bank whose slots Inventory Setups' side panel highlights for the open setup, in the
 * setup's highlight color. Only for setups with "Highlight differences" on.
 */
@Singleton
public class DifferencesOverlay extends Overlay
{
	// how much of the highlight color shows through over the item
	private static final int FILL_ALPHA = 50;

	private static final int[] RUNE_POUCHES = {
		ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER,
	};
	// the fourth slot is the divine rune pouch's, and stays empty in the others
	private static final int[] RUNE_POUCH_TYPES = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4,
	};
	private static final int[] RUNE_POUCH_QUANTITIES = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4,
	};

	private final Client client;
	private final SetupPickerConfig config;
	private final ItemManager itemManager;

	// null when there's no open setup, or it doesn't highlight its differences
	private volatile SetupHighlight highlight;

	@Inject
	DifferencesOverlay(Client client, SetupPickerConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// drawn first, so that the picker and anything else over the bank goes on top of the outlines
		setPriority(PRIORITY_LOW);
	}

	public void setHighlight(SetupHighlight highlight)
	{
		this.highlight = highlight;
	}

	private List<SetupHighlight.Slot> current(int containerId)
	{
		final ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return Collections.emptyList();
		}
		final Item[] items = container.getItems();
		final List<SetupHighlight.Slot> slots = new ArrayList<>(items.length);
		for (Item item : items)
		{
			slots.add(new SetupHighlight.Slot(item.getId(), item.getQuantity()));
		}
		return slots;
	}

	/**
	 * The runes in the rune pouch in the player's inventory, or null when there's no rune pouch there.
	 */
	private List<SetupHighlight.Slot> currentRunePouch()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		boolean carried = false;
		for (int pouch : RUNE_POUCHES)
		{
			carried |= inventory != null && inventory.contains(pouch);
		}
		if (!carried)
		{
			return null;
		}
		// the varbits hold each rune by its position in this enum, 0 for none
		final EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		final List<SetupHighlight.Slot> slots = new ArrayList<>(RUNE_POUCH_TYPES.length);
		for (int i = 0; i < RUNE_POUCH_TYPES.length; i++)
		{
			final int type = client.getVarbitValue(RUNE_POUCH_TYPES[i]);
			slots.add(type == 0 ? SetupHighlight.Slot.EMPTY
				: new SetupHighlight.Slot(runes.getIntValue(type), client.getVarbitValue(RUNE_POUCH_QUANTITIES[i])));
		}
		return slots;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final SetupHighlight highlight = this.highlight;
		if (!config.highlightDifferences() || highlight == null)
		{
			return null;
		}
		final Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.isHidden())
		{
			return null;
		}
		final List<SetupHighlight.Slot> differences = highlight.differences(
			current(InventoryID.INV), current(InventoryID.WORN), currentRunePouch(), ItemVariationMapping::map);
		if (differences.isEmpty())
		{
			return null;
		}

		// the bank has items unnoted, and placeholders for those that have run out
		final Set<Integer> exact = new HashSet<>();
		final Set<Integer> variants = new HashSet<>();
		for (SetupHighlight.Slot slot : differences)
		{
			final int id = itemManager.canonicalize(slot.id);
			exact.add(id);
			if (slot.fuzzy)
			{
				variants.add(ItemVariationMapping.map(id));
			}
		}

		final Widget[] children = items.getDynamicChildren();
		if (children == null)
		{
			return null;
		}
		final Color color = config.overrideDifferenceColor() ? config.differenceColor() : highlight.getColor();
		final Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), FILL_ALPHA);
		// the bank scrolls, so leave out what has been scrolled out of sight
		final Shape clip = graphics.getClip();
		graphics.clip(items.getBounds());
		for (Widget child : children)
		{
			if (child == null || child.isHidden() || child.getItemId() <= 0)
			{
				continue;
			}
			final int id = itemManager.canonicalize(child.getItemId());
			if (!exact.contains(id) && !variants.contains(ItemVariationMapping.map(id)))
			{
				continue;
			}
			final Rectangle slot = child.getBounds();
			graphics.setColor(fill);
			graphics.fill(slot);
			graphics.setColor(color);
			graphics.drawRect(slot.x, slot.y, slot.width - 1, slot.height - 1);
		}
		graphics.setClip(clip);
		return null;
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * The game's own interface sprites, for drawing the lists in the game's chrome.
 * <p>
 * Sprites are looked up the way the game looks them up when it draws an interface: the client's sprite overrides
 * first, then the game cache. Overrides are how the Resource Packs plugin and RuneLite's Interface Styles reskin
 * interfaces, so going through them keeps the lists matching the bank beside them. The overrides are only ever
 * read, never written.
 * <p>
 * Packs change while the game runs. Resource Packs applies its sprites late, after a download and again on login,
 * and announces nothing, so {@link #refresh()} compares the override behind every sprite it holds with the one now
 * in place and starts again on any difference. The bank's separator color is read from the bank itself, since a
 * color pack recolors those lines rather than a sprite.
 * <p>
 * Client thread only, which is where overlays render.
 */
@Singleton
public class GameSprites implements PickerSkin.Sprites
{
	// The bank's own separator lines, as the game draws them without a color pack
	private static final Color DEFAULT_LINE = new Color(0x2e2b23);

	// Config groups whose changes can reskin interfaces: Resource Packs' and Interface Styles'
	private static final Set<String> THEME_GROUPS = new HashSet<>(Arrays.asList("resourcepacks", "interfaceStyles"));

	// The keys in RuneLite's own config group that turn those plugins on and off. The rest of that group is
	// written all the time (every overlay moved, the window resized), so only these mean a reload.
	private static final String RUNELITE_GROUP = "runelite";
	private static final Set<String> THEME_PLUGIN_KEYS = new HashSet<>(Arrays.asList("resourcepacksplugin", "interfacestylesplugin"));

	private final Client client;

	// The sprites asked for, and the override each came from, or null for the cache
	private final Map<Integer, BufferedImage> sprites = new HashMap<>();
	private final Map<Integer, SpritePixels> sources = new HashMap<>();
	// The sprites that couldn't be had, and the client tick they were last asked for in
	private final Map<Integer, Integer> missing = new HashMap<>();

	// Bumped whenever the sprites are thrown away, so anything made from them can be made again
	private int version;
	// Set from any thread when a theme setting changes, and acted on by the next refresh
	private volatile boolean invalidated;
	// The client tick of the last refresh, so that it is done once a tick however often it's asked for
	private int refreshedCycle = -1;
	private Color line = DEFAULT_LINE;

	@Inject
	GameSprites(Client client)
	{
		this.client = client;
	}

	/**
	 * The pixels of a sprite, trimmed to the part of it that isn't see-through, or null when neither the overrides
	 * nor the cache have it. One that is all see-through is {@link PickerSkin#EMPTY}, not missing: packs leave sprites
	 * blank on purpose, such as a scrollbar with no track.
	 * <p>
	 * The cache may not have loaded a sprite yet when it is first asked for; it is asked again each client tick until
	 * it has, so the game's own sprites are drawn as soon as they can be.
	 */
	@Override
	public BufferedImage get(int id)
	{
		final BufferedImage sprite = sprites.get(id);
		if (sprite != null)
		{
			return sprite;
		}
		final Integer missedIn = missing.get(id);
		if (missedIn != null && missedIn == refreshedCycle)
		{
			return null;
		}

		final SpritePixels override = override(id);
		final SpritePixels pixels = override != null ? override : fromCache(id);
		if (pixels == null)
		{
			missing.put(id, refreshedCycle);
			return null;
		}
		final BufferedImage image = pixels.getWidth() <= 0 || pixels.getHeight() <= 0 ? PickerSkin.EMPTY : PickerSkin.trim(pixels.toBufferedImage());
		missing.remove(id);
		sprites.put(id, image);
		sources.put(id, override);
		return image;
	}

	private SpritePixels override(int id)
	{
		final Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		return overrides == null ? null : overrides.get(id);
	}

	private SpritePixels fromCache(int id)
	{
		final IndexDataBase index = client.getIndexSprites();
		if (index == null)
		{
			return null;
		}
		final SpritePixels[] frames = client.getSprites(index, id, 0);
		return frames == null || frames.length == 0 ? null : frames[0];
	}

	/**
	 * The client tick the sprites were last brought up to date in.
	 */
	public int getCycle()
	{
		return refreshedCycle;
	}

	/**
	 * Changes whenever the sprites are replaced.
	 */
	public int getVersion()
	{
		return version;
	}

	/**
	 * The color of the bank's separator lines.
	 */
	public Color getLine()
	{
		return line;
	}

	/**
	 * Brings the sprites up to date with the current theme. Call at the start of every render that uses them; the
	 * work is done at most once a client tick. Comparing each sprite's override with the one in place is the only
	 * way to notice a pack being applied, and is a few map lookups.
	 */
	public void refresh()
	{
		final int cycle = client.getGameCycle();
		if (cycle == refreshedCycle)
		{
			return;
		}
		refreshedCycle = cycle;

		if (invalidated || overridesChanged())
		{
			invalidated = false;
			sprites.clear();
			sources.clear();
			missing.clear();
			version++;
		}

		// the bank's line under its tabs, while the bank is open, and the last one seen while it isn't
		final Widget tabsLine = client.getWidget(InterfaceID.Bankmain.TABS_LINE0);
		if (tabsLine != null && !tabsLine.isHidden() && (tabsLine.getTextColor() & 0xffffff) != (line.getRGB() & 0xffffff))
		{
			line = new Color(tabsLine.getTextColor() & 0xffffff);
		}
	}

	private boolean overridesChanged()
	{
		final Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		for (Map.Entry<Integer, SpritePixels> source : sources.entrySet())
		{
			if ((overrides == null ? null : overrides.get(source.getKey())) != source.getValue())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Notes a config change that might have reskinned the game's interfaces, so that the next refresh loads every
	 * sprite again. Safe to call from any thread.
	 */
	public void onConfigChanged(String group, String key)
	{
		if (THEME_GROUPS.contains(group) || RUNELITE_GROUP.equals(group) && THEME_PLUGIN_KEYS.contains(key))
		{
			invalidated = true;
		}
	}
}

package com.setuppicker;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.util.Text;

/**
 * Mouse and keyboard handling for the picker. Events that land on the picker, and all typing while its
 * search box has focus, are consumed so they don't also reach the game.
 *
 * <p>Key listeners run in the order they were registered, and other plugins' usually come first. Remapping
 * plugins rewrite key presses and consume typed characters before this listener sees them, so it works from
 * the physical key of each press instead. {@link ChatboxKeyGuard} keeps the chatbox out of the way meanwhile.
 */
@Singleton
public class PickerInput extends MouseAdapter implements KeyListener, MouseWheelListener
{
	// How far the mouse has to go with the title bar held for it to be a drag of the list, not a click
	private static final int DRAG_THRESHOLD = 4;
	// A held scrollbar arrow keeps scrolling after a moment, then steadily, as the game's do
	private static final long ARROW_DELAY_MILLIS = 250;
	private static final long ARROW_REPEAT_MILLIS = 50;
	private static final int MODIFIER_MASK = InputEvent.CTRL_DOWN_MASK | InputEvent.META_DOWN_MASK
		| InputEvent.ALT_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK;
	// what the core Key Remapping plugin shows in the chatbox while it keeps typing out of the chat
	static final String PRESS_ENTER_TO_CHAT = "Press Enter to Chat...";

	private final Client client;
	private final SetupPickerPlugin plugin;
	private final SetupPickerConfig config;
	private final SetupPickerOverlay overlay;
	private final PickerModel model;
	private final PlatformModifier platformModifier;

	// The hotkey's own key press can also produce a typed character, which shouldn't end up in the search box
	private boolean swallowNextTyped;
	private final Set<Integer> swallowedPresses = new HashSet<>();
	// While the scrollbar is being dragged: how far below the top of its thumb it was taken hold of. Else -1.
	private int scrollGrab = -1;
	// While the title bar of the list beside the bank is held: where the mouse went down, and how far that was
	// from the list's top left corner. Else null.
	private Point titlePress;
	private Point titleGrab;
	private boolean titleCollapsed;
	// whether it has been moved far enough since to be dragging the list
	private boolean moving;
	// While a scrollbar arrow is held: the way it scrolls, when it was pressed and where the mouse is. Else 0.
	// Set by the mouse and read each client tick.
	private volatile int arrowHeld;
	private volatile long arrowPressedAt;
	private volatile Point arrowMouse;
	private long arrowRepeatedAt;

	@Inject
	PickerInput(Client client, SetupPickerPlugin plugin, SetupPickerConfig config, SetupPickerOverlay overlay,
		PickerModel model, PlatformModifier platformModifier)
	{
		this.platformModifier = platformModifier;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.overlay = overlay;
		this.model = model;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		// in case the release that ends a drag of the scrollbar, or a hold of its arrow, never came
		scrollGrab = -1;
		arrowHeld = 0;
		model.setScrollbarDragged(false);
		// or the one that ends a drag of the list
		titlePress = null;
		moving = false;
		overlay.endDrag();
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			// clicking back into the game ends the search and dismisses the popup
			if (model.view().isSearchFocused())
			{
				model.resetSearch();
			}
			return e;
		}

		if (SwingUtilities.isLeftMouseButton(e))
		{
			if (grabScrollbar(layout, e))
			{
				// nothing else is under it
			}
			else if (layout.isPalette())
			{
				clickRow(layout, e);
			}
			else if (layout.getHeader().contains(e.getPoint()))
			{
				// Collapsed or expanded when it's let go, unless it has been dragged somewhere by then
				titlePress = e.getPoint();
				// from where the title bar's corner is, which for a list collapsed to an upright tab is the tab's
				titleGrab = new Point(e.getX() - layout.getBounds().x,
					Math.min(e.getY() - layout.getBounds().y, layout.getTitle().y - layout.getBounds().y + PickerLayout.HEADER_HEIGHT - 1));
				titleCollapsed = layout.isCollapsed();
			}
			else if (layout.getSearch() != null && layout.getSearch().contains(e.getPoint()))
			{
				model.setSearchFocused(true);
			}
			else
			{
				clickRow(layout, e);
			}
		}
		else if (SwingUtilities.isRightMouseButton(e) && !layout.isPalette() && layout.getHeader().contains(e.getPoint()))
		{
			// back beside the bank, if it has been dragged elsewhere
			plugin.setBankOffset(null);
		}
		e.consume();
		return e;
	}

	/**
	 * While the mouse is over the picker, the game is told it has left the canvas instead. Otherwise whatever
	 * is underneath (bank items, when the popup is over the bank) is still hovered, and its tooltip gets drawn
	 * on top of the picker.
	 */
	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			overlay.setMouse(null);
			return e;
		}
		// the game no longer knows where the mouse is, so the overlay is told for its own hover highlight
		overlay.setMouse(e.getPoint());
		return new MouseEvent(e.getComponent(), e.getID(), e.getWhen(), e.getModifiersEx(), -1, -1,
			e.getClickCount(), e.isPopupTrigger(), e.getButton());
	}

	/**
	 * Keeps scrolling while a scrollbar arrow is held down with the mouse on it: after a moment, then a row at a
	 * time, steadily. Client thread, each client tick.
	 */
	void tick()
	{
		final int direction = arrowHeld;
		final long now = System.currentTimeMillis();
		if (direction == 0 || now - arrowPressedAt < ARROW_DELAY_MILLIS || now - arrowRepeatedAt < ARROW_REPEAT_MILLIS)
		{
			return;
		}
		final PickerLayout layout = overlay.getLayout();
		final Point mouse = arrowMouse;
		final int rows = model.view().getRows().size();
		final Rectangle arrow = layout == null ? null : direction < 0 ? layout.getScrollUp(rows) : layout.getScrollDown(rows);
		if (arrow != null && mouse != null && arrow.contains(mouse))
		{
			arrowRepeatedAt = now;
			model.scrollBy(direction);
		}
	}

	/**
	 * Take hold of the scrollbar if that's what was pressed. Pressing it above or below its thumb brings the
	 * thumb there first. Its arrows, when it has them, scroll a row.
	 */
	private boolean grabScrollbar(PickerLayout layout, MouseEvent e)
	{
		final PickerModel.View view = model.view();
		final int rowCount = view.getRows().size();
		final Rectangle bar = layout.getScrollbar(rowCount);
		if (bar == null || !bar.contains(e.getPoint()))
		{
			return false;
		}
		final Rectangle up = layout.getScrollUp(rowCount);
		final Rectangle down = layout.getScrollDown(rowCount);
		if (up != null && up.contains(e.getPoint()) || down != null && down.contains(e.getPoint()))
		{
			arrowHeld = up != null && up.contains(e.getPoint()) ? -1 : 1;
			arrowMouse = e.getPoint();
			arrowPressedAt = System.currentTimeMillis();
			arrowRepeatedAt = arrowPressedAt;
			model.scrollBy(arrowHeld);
			return true;
		}
		final Rectangle thumb = layout.getScrollThumb(rowCount, view.getScroll());
		scrollGrab = thumb.contains(e.getPoint()) ? e.getY() - thumb.y : thumb.height / 2;
		model.setScrollbarDragged(true);
		model.scrollTo(layout.scrollAt(rowCount, e.getY() - scrollGrab));
		return true;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (titlePress != null)
		{
			moving |= titlePress.distance(e.getPoint()) >= DRAG_THRESHOLD;
			if (moving)
			{
				overlay.dragTo(new Point(e.getX() - titleGrab.x, e.getY() - titleGrab.y));
			}
			e.consume();
			return e;
		}
		if (arrowHeld != 0)
		{
			arrowMouse = e.getPoint();
			e.consume();
			return e;
		}
		final PickerLayout layout = overlay.getLayout();
		if (scrollGrab < 0 || layout == null)
		{
			return e;
		}
		// wherever the mouse has got to, as with any scrollbar
		model.scrollTo(layout.scrollAt(model.view().getRows().size(), e.getY() - scrollGrab));
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (arrowHeld != 0)
		{
			arrowHeld = 0;
			e.consume();
		}
		if (scrollGrab >= 0)
		{
			scrollGrab = -1;
			model.setScrollbarDragged(false);
			e.consume();
		}
		if (titlePress != null)
		{
			if (moving)
			{
				final Point offset = overlay.getDragOffset();
				if (offset != null)
				{
					plugin.setBankOffset(offset);
				}
			}
			else
			{
				model.resetSearch();
				plugin.setCollapsed(!titleCollapsed);
			}
			titlePress = null;
			moving = false;
			// only once it's saved, so that the list isn't drawn back where it was in between
			overlay.endDrag();
			e.consume();
		}
		return e;
	}

	private void clickRow(PickerLayout layout, MouseEvent e)
	{
		final int row = layout.rowAt(e.getPoint());
		final PickerModel.View view = model.view();
		final List<PickerRow> rows = view.getRows();
		if (row < 0 || view.getScroll() + row >= rows.size())
		{
			return;
		}
		activate(rows.get(view.getScroll() + row));
	}

	/**
	 * Do what picking a row does: open or close its setup, or go to or back from a section's page.
	 */
	private void activate(PickerRow row)
	{
		if (row.isBack())
		{
			model.closeSection();
		}
		else if (row.isHeader())
		{
			// headings are only for show unless sections have pages
			model.openSection(row);
		}
		else
		{
			plugin.toggleSetup(row.getSetup());
			model.resetSearch();
		}
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			return e;
		}
		model.scrollBy(e.getWheelRotation());
		e.consume();
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		final int code = keyCode(e);
		if (isHotkey(e, code))
		{
			if (model.view().isPaletteOpen())
			{
				model.resetSearch();
			}
			else if (client.getGameState() == GameState.LOGGED_IN)
			{
				model.openPalette();
			}
			else
			{
				return;
			}
			swallowNextTyped = true;
			swallow(e, code);
			return;
		}
		// any other key means the hotkey's typed character, if it had one, has been and gone
		swallowNextTyped = false;

		if (!model.view().isSearchFocused())
		{
			return;
		}

		if (isSelectAll(e, code))
		{
			model.selectQuery();
			swallow(e, code);
			return;
		}

		switch (code)
		{
			case KeyEvent.VK_ESCAPE:
				model.resetSearch();
				break;
			case KeyEvent.VK_ENTER:
				final PickerRow row = model.getSelectedRow();
				if (row != null)
				{
					activate(row);
				}
				else
				{
					model.resetSearch();
				}
				break;
			case KeyEvent.VK_LEFT:
				if (model.view().getQuery().isEmpty())
				{
					// nothing to move through: back out of the section's page
					model.closeSection();
				}
				else
				{
					model.moveCaret(-1);
				}
				break;
			case KeyEvent.VK_RIGHT:
				model.moveCaret(1);
				break;
			case KeyEvent.VK_HOME:
				model.moveCaret(-Integer.MAX_VALUE);
				break;
			case KeyEvent.VK_END:
				model.moveCaret(Integer.MAX_VALUE);
				break;
			case KeyEvent.VK_DELETE:
				model.deleteForward();
				break;
			case KeyEvent.VK_UP:
				model.moveSelection(-1);
				break;
			case KeyEvent.VK_DOWN:
				model.moveSelection(1);
				break;
			case KeyEvent.VK_TAB:
				model.moveSelection(e.isShiftDown() ? -1 : 1);
				break;
			case KeyEvent.VK_PAGE_UP:
				model.pageSelection(-1);
				break;
			case KeyEvent.VK_PAGE_DOWN:
				model.pageSelection(1);
				break;
			case KeyEvent.VK_BACK_SPACE:
				model.backspace();
				break;
			default:
				final char c = typedChar(e, code);
				if (c != 0)
				{
					model.typeChar(c);
				}
				break;
		}
		swallow(e, code);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		// The search text is built from key presses (see typedChar), so typed events only need keeping from the game
		if (swallowNextTyped || model.view().isSearchFocused())
		{
			swallowNextTyped = false;
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		// Only releases of presses that were swallowed: a key that was already held when the search started
		// (say, a camera key) must still be seen being released by the game
		if (swallowedPresses.remove(keyCode(e)))
		{
			e.consume();
		}
	}

	private void swallow(KeyEvent e, int code)
	{
		swallowedPresses.add(code);
		e.consume();
	}

	/**
	 * The key that was physically pressed. Listeners registered before this one may have rewritten the event's
	 * key code (Key Remapping turns W into Up, for one), but they leave the extended key code alone, which is
	 * also what RuneLite's own keybinds match on.
	 */
	private static int keyCode(KeyEvent e)
	{
		final int extended = e.getExtendedKeyCode();
		return extended != KeyEvent.VK_UNDEFINED ? extended : e.getKeyCode();
	}

	/**
	 * The character a key press types, or 0 for none. Taken from the press rather than from typed events,
	 * because remapping plugins consume those, and blank the character of the presses they rewrite.
	 */
	private static char typedChar(KeyEvent e, int code)
	{
		if (e.isControlDown() || e.isMetaDown())
		{
			return 0;
		}
		final char c = e.getKeyChar();
		if (c != KeyEvent.CHAR_UNDEFINED)
		{
			return c >= ' ' && c != KeyEvent.VK_DELETE ? c : 0;
		}
		// a rewritten press: work the character out from the key
		if (code >= KeyEvent.VK_A && code <= KeyEvent.VK_Z)
		{
			return (char) ((e.isShiftDown() ? 'A' : 'a') + code - KeyEvent.VK_A);
		}
		if (code >= KeyEvent.VK_0 && code <= KeyEvent.VK_9)
		{
			return (char) ('0' + code - KeyEvent.VK_0);
		}
		if (code >= KeyEvent.VK_NUMPAD0 && code <= KeyEvent.VK_NUMPAD9)
		{
			return (char) ('0' + code - KeyEvent.VK_NUMPAD0);
		}
		switch (code)
		{
			case KeyEvent.VK_SPACE:
				return ' ';
			case KeyEvent.VK_MINUS:
				return '-';
			case KeyEvent.VK_EQUALS:
				return '=';
			default:
				return 0;
		}
	}

	// Ctrl+A or Cmd+A. Either is taken on any platform, as neither means anything else in the search box.
	private static boolean isSelectAll(KeyEvent e, int code)
	{
		final int modifiers = e.getModifiersEx() & MODIFIER_MASK;
		return code == KeyEvent.VK_A && (modifiers == InputEvent.CTRL_DOWN_MASK || modifiers == InputEvent.META_DOWN_MASK);
	}

	private boolean isHotkey(KeyEvent e, int code)
	{
		if (code != config.openKey().getKeyCode() || code == KeyEvent.VK_UNDEFINED)
		{
			return false;
		}
		final int wanted = config.requireModifier() ? platformModifier.get() : 0;
		if ((e.getModifiersEx() & MODIFIER_MASK) != wanted)
		{
			return false;
		}
		// Without a modifier the hotkey is a plain key, which has to stay typeable in the search box, and in the
		// game wherever it takes typing: a K pressed while chatting is the letter K
		return wanted != 0 || !model.view().isSearchFocused() && !(typedChar(e, code) != 0 && gameTakesTyping());
	}

	/**
	 * Whether a key that types a character would type it into the game: into an input box, such as the bank's
	 * search or an "Enter amount", or into the chat, unless Key Remapping is keeping typing out of the chat until
	 * Enter is pressed.
	 */
	private boolean gameTakesTyping()
	{
		if (client.getFocusedInputFieldWidget() != null)
		{
			return true;
		}
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (chatbox == null || chatbox.getOnKeyListener() == null)
		{
			return false;
		}
		final Widget line = client.getWidget(InterfaceID.Chatbox.INPUT);
		return line == null || !Text.removeTags(line.getText()).endsWith(PRESS_ENTER_TO_CHAT);
	}
}

package com.setuppicker;

import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where the picker's parts are on the canvas for one frame. Shared by painting and mouse hit-testing.
 */
public final class PickerLayout
{
	static final int HEADER_HEIGHT = 20;
	static final int SEARCH_HEIGHT = 20;
	static final int PADDING = 3;
	static final int GAP = 4;
	static final int ROW_HEIGHT_ICONS = 20;
	static final int ROW_HEIGHT_TEXT = 16;
	static final int FOOTER_HEIGHT = 16;
	static final int COLLAPSED_WIDTH = HEADER_HEIGHT;
	static final int COLLAPSED_LENGTH = 96;
	static final int SCROLL_THUMB_MIN = 12;

	/**
	 * How much room the picker's chrome takes, which depends on what it is drawn with.
	 */
	public static final class Frame
	{
		/**
		 * Drawn in flat colors: a thin border inside the padding, and a narrow scrollbar.
		 */
		public static final Frame FLAT = new Frame(0, 0, 6, 0);

		/**
		 * Drawn with the game's sprites: the bank's steel frame round it and under its title, and the game's
		 * scrollbar with its arrows.
		 */
		public static final Frame GAME = new Frame(6, 6, 16, 16);

		// how thick the frame round everything is, outside the width set for the list and the padding inside it
		final int edge;
		// how thick the divider between the title bar and the rest is
		final int divider;
		final int scrollbarWidth;
		// how tall each of the scrollbar's arrows is, or 0 for none
		final int scrollArrow;

		private Frame(int edge, int divider, int scrollbarWidth, int scrollArrow)
		{
			this.edge = edge;
			this.divider = divider;
			this.scrollbarWidth = scrollbarWidth;
			this.scrollArrow = scrollArrow;
		}
	}

	private final Rectangle bounds;
	private final Rectangle header;
	private final Rectangle title;
	private final Rectangle search;
	private final Rectangle list;
	private final Rectangle footer;
	private final int rowHeight;
	private final int visibleRows;
	private final Frame frame;

	private PickerLayout(Rectangle bounds, Rectangle header, Rectangle title, Rectangle search, Rectangle list,
		Rectangle footer, int rowHeight, int visibleRows, Frame frame)
	{
		this.bounds = bounds;
		this.header = header;
		this.title = title;
		this.search = search;
		this.list = list;
		this.footer = footer;
		this.rowHeight = rowHeight;
		this.visibleRows = visibleRows;
		this.frame = frame;
	}

	/**
	 * The hotkey-opened popup, in flat colors.
	 *
	 * @see #computePalette(Rectangle, int, int, int, int, Frame)
	 */
	public static PickerLayout computePalette(Rectangle area, int width, int setupCount, int rowHeight, int maxRows)
	{
		return computePalette(area, width, setupCount, rowHeight, maxRows, Frame.FLAT);
	}

	/**
	 * The hotkey-opened popup: centered horizontally in the game area, in its upper part.
	 *
	 * @param area       the canvas
	 * @param setupCount number of rows to list (setups and section headings), after the search is applied
	 * @param maxRows    most rows to show before scrolling
	 */
	public static PickerLayout computePalette(Rectangle area, int width, int setupCount, int rowHeight, int maxRows,
		Frame frame)
	{
		// the frame goes round the width asked for, so that what's inside has as much room whatever draws it
		width = Math.min(width + 2 * frame.edge, area.width);
		final int chrome = HEADER_HEIGHT + SEARCH_HEIGHT + FOOTER_HEIGHT + 4 * PADDING + 2 * frame.edge + frame.divider;
		final int fittingRows = Math.max(1, (area.height - chrome) / rowHeight);
		final int visibleRows = Math.max(1, Math.min(setupCount, Math.min(maxRows, fittingRows)));

		final int x = area.x + (area.width - width) / 2;
		// Anchored where it would sit with a full list, so it doesn't jump around as typing narrows the results
		final int fullHeight = chrome + Math.min(maxRows, fittingRows) * rowHeight;
		final int y = area.y + Math.max(0, Math.min(area.height / 6, area.height - fullHeight));

		final Rectangle title = new Rectangle(x + frame.edge, y + frame.edge, width - 2 * frame.edge, HEADER_HEIGHT);
		final Rectangle header = new Rectangle(x, y, width, frame.edge + HEADER_HEIGHT);
		final int inset = frame.edge + PADDING;
		final Rectangle search = new Rectangle(x + inset, title.y + title.height + frame.divider + PADDING,
			width - 2 * inset, SEARCH_HEIGHT);
		final Rectangle list = new Rectangle(x + inset, search.y + search.height + PADDING, width - 2 * inset, visibleRows * rowHeight);
		final Rectangle footer = new Rectangle(x + inset, list.y + list.height + PADDING, width - 2 * inset, FOOTER_HEIGHT);
		final Rectangle bounds = new Rectangle(x, y, width, footer.y + footer.height + PADDING + frame.edge - y);
		return new PickerLayout(bounds, header, title, search, list, footer, rowHeight, visibleRows, frame);
	}

	/**
	 * The list docked beside the bank, in flat colors.
	 *
	 * @see #compute(Rectangle, int, boolean, int, boolean, boolean, int, int, int, Frame)
	 */
	public static PickerLayout compute(Rectangle bank, int canvasWidth, boolean preferLeft, int width,
		boolean collapsed, boolean uprightTab, int setupCount, int rowHeight, int maxRows)
	{
		return compute(bank, canvasWidth, preferLeft, width, collapsed, uprightTab, setupCount, rowHeight, maxRows, Frame.FLAT);
	}

	/**
	 * The list docked beside the bank.
	 *
	 * @param bank       bounds of the bank interface
	 * @param preferLeft sit left of the bank when both sides have room
	 * @param uprightTab when collapsed, be a narrow upright tab rather than just the title bar
	 * @param setupCount number of rows to list (setups and section headings), after the search is applied
	 * @param maxRows    most rows to show before scrolling, or 0 for as many as fit down the bank's side
	 */
	public static PickerLayout compute(Rectangle bank, int canvasWidth, boolean preferLeft, int width,
		boolean collapsed, boolean uprightTab, int setupCount, int rowHeight, int maxRows, Frame frame)
	{
		final boolean upright = collapsed && uprightTab;
		// A narrow tab standing against the bank's edge with its title running up it, or else the list with its
		// frame round the width asked for
		width = (upright ? COLLAPSED_WIDTH : width) + 2 * frame.edge;
		final int leftX = bank.x - GAP - width;
		final int rightX = bank.x + bank.width + GAP;
		final boolean leftFits = leftX >= 0;
		final boolean rightFits = rightX + width <= canvasWidth;

		final int x;
		if (leftFits && (preferLeft || !rightFits))
		{
			x = leftX;
		}
		else if (rightFits)
		{
			x = rightX;
		}
		else
		{
			// No room on either side (fixed mode): sit on top of the bank's edge instead
			x = preferLeft ? bank.x : bank.x + bank.width - width;
		}
		final int y = bank.y;

		if (upright)
		{
			final Rectangle tab = new Rectangle(x, y, width, Math.min(COLLAPSED_LENGTH, bank.height));
			final Rectangle title = new Rectangle(x + frame.edge, y + frame.edge, COLLAPSED_WIDTH, tab.height - 2 * frame.edge);
			return new PickerLayout(tab, tab, title, null, null, null, rowHeight, 0, frame);
		}
		return docked(x, y, width, collapsed, bank.y + bank.height, setupCount, rowHeight, maxRows, frame);
	}

	/**
	 * The list of the bank's, dragged away from the bank's side, in flat colors.
	 *
	 * @see #computeMoved(Rectangle, Rectangle, Point, int, boolean, int, int, int, Frame)
	 */
	public static PickerLayout computeMoved(Rectangle bank, Rectangle canvas, Point offset, int width,
		boolean collapsed, int setupCount, int rowHeight, int maxRows)
	{
		return computeMoved(bank, canvas, offset, width, collapsed, setupCount, rowHeight, maxRows, Frame.FLAT);
	}

	/**
	 * The list of the bank's, dragged away from the bank's side to somewhere of its own.
	 *
	 * @param offset     where its top left corner is from the bank's, as drawn without a frame; see {@link #movedCorner}
	 * @param setupCount number of rows to list (setups and section headings), after the search is applied
	 * @param maxRows    most rows to show before scrolling, or 0 for as many as fit above the canvas's bottom
	 */
	public static PickerLayout computeMoved(Rectangle bank, Rectangle canvas, Point offset, int width,
		boolean collapsed, int setupCount, int rowHeight, int maxRows, Frame frame)
	{
		final Point corner = movedCorner(bank, canvas, offset, width, frame);
		return docked(corner.x, corner.y, width + 2 * frame.edge, collapsed, canvas.y + canvas.height, setupCount, rowHeight,
			maxRows, frame);
	}

	/**
	 * Where a dragged list's top left corner goes, frame and all, kept on the canvas.
	 * <p>
	 * The place saved for it is where the list is without a frame. A frame grows it away from the bank, so that
	 * the gap left to the bank stays as it was: to the left for a list left of the bank, to the right for one right
	 * of it, and downwards. Turning the frame on and off moves nothing but the far edges, and the place saved stays
	 * the same either way.
	 *
	 * @param offset where the list's top left corner is from the bank's, as drawn without a frame
	 * @param width  the width set for the list, which its frame goes round
	 */
	public static Point movedCorner(Rectangle bank, Rectangle canvas, Point offset, int width, Frame frame)
	{
		final int x = bank.x + offset.x;
		return clamp(new Point(leftOf(bank, x, width) ? x - 2 * frame.edge : x, bank.y + offset.y), width, canvas, frame);
	}

	/**
	 * The place to save for a dragged list whose top left corner, frame and all, is here: the other way round from
	 * {@link #movedCorner}.
	 */
	public static Point offsetFor(Rectangle bank, Point corner, int width, Frame frame)
	{
		final int framed = corner.x + 2 * frame.edge;
		final int x = leftOf(bank, framed, width) ? framed : corner.x;
		return new Point(x - bank.x, corner.y - bank.y);
	}

	/**
	 * The place to save for a dragged list, moved as little as keeps it on the canvas when drawn. Which side of the
	 * bank it is on, and so which way its frame grows, is kept from the place it was given, so that the place saved
	 * is drawn where the list was let go, with the frame or without it.
	 *
	 * @param offset where the list's top left corner is from the bank's, as drawn without a frame
	 */
	public static Point keepOnCanvas(Rectangle bank, Rectangle canvas, Point offset, int width, Frame frame)
	{
		final int x = bank.x + offset.x;
		final int grown = leftOf(bank, x, width) ? 2 * frame.edge : 0;
		final Point corner = clamp(new Point(x - grown, bank.y + offset.y), width, canvas, frame);
		return new Point(corner.x + grown - bank.x, corner.y - bank.y);
	}

	/**
	 * Whether a list at this place without its frame is to the left of the bank, by their middles.
	 */
	private static boolean leftOf(Rectangle bank, int x, int width)
	{
		return x + width / 2 < bank.x + bank.width / 2;
	}

	/**
	 * The nearest place to a corner that keeps a list of this width, frame and all, or at least its title bar, on the
	 * canvas, where it can be taken hold of again.
	 *
	 * @param width the width set for the list, which its frame goes round
	 * @param frame what the list is drawn with
	 */
	public static Point clamp(Point corner, int width, Rectangle canvas, Frame frame)
	{
		final int x = Math.max(canvas.x, Math.min(corner.x, canvas.x + canvas.width - width - 2 * frame.edge));
		final int y = Math.max(canvas.y, Math.min(corner.y, canvas.y + canvas.height - HEADER_HEIGHT - 2 * frame.edge));
		return new Point(x, y);
	}

	/**
	 * @param bottom how far down the canvas the list may reach
	 */
	private static PickerLayout docked(int x, int y, int width, boolean collapsed, int bottom, int setupCount,
		int rowHeight, int maxRows, Frame frame)
	{
		final Rectangle title = new Rectangle(x + frame.edge, y + frame.edge, width - 2 * frame.edge, HEADER_HEIGHT);
		if (collapsed)
		{
			// just the title bar
			final Rectangle bar = new Rectangle(x, y, width, HEADER_HEIGHT + 2 * frame.edge);
			return new PickerLayout(bar, bar, title, null, null, null, rowHeight, 0, frame);
		}
		final Rectangle header = new Rectangle(x, y, width, frame.edge + HEADER_HEIGHT);
		final int inset = frame.edge + PADDING;
		final Rectangle search = new Rectangle(x + inset, title.y + title.height + frame.divider + PADDING,
			width - 2 * inset, SEARCH_HEIGHT);
		final int listY = search.y + search.height + PADDING;
		final int fittingRows = Math.max(1, (bottom - listY - PADDING - frame.edge) / rowHeight);
		// always leave one row's worth of space for the "no setups" message
		final int visibleRows = Math.max(1, Math.min(setupCount, maxRows > 0 ? Math.min(maxRows, fittingRows) : fittingRows));
		final Rectangle list = new Rectangle(x + inset, listY, width - 2 * inset, visibleRows * rowHeight);
		final Rectangle bounds = new Rectangle(x, y, width, list.y + list.height + PADDING + frame.edge - y);
		return new PickerLayout(bounds, header, title, search, list, null, rowHeight, visibleRows, frame);
	}

	public Rectangle getBounds()
	{
		return bounds;
	}

	/**
	 * Where the title bar can be taken hold of: the title bar and the frame above and beside it, or the whole of
	 * the collapsed list.
	 */
	public Rectangle getHeader()
	{
		return header;
	}

	/**
	 * The title bar itself, inside the frame.
	 */
	public Rectangle getTitle()
	{
		return title;
	}

	public Frame getFrame()
	{
		return frame;
	}

	/**
	 * How far down from the top the divider under the title bar is, or 0 when there is none.
	 */
	public int getDivider()
	{
		return frame.divider > 0 && list != null ? title.y + title.height - bounds.y : 0;
	}

	/**
	 * The search box, or null when collapsed.
	 */
	public Rectangle getSearch()
	{
		return search;
	}

	/**
	 * The area holding the rows, or null when collapsed.
	 */
	public Rectangle getList()
	{
		return list;
	}

	/**
	 * The key hint strip of the popup, or null for the list beside the bank.
	 */
	public Rectangle getFooter()
	{
		return footer;
	}

	public boolean isPalette()
	{
		return footer != null;
	}

	public boolean isCollapsed()
	{
		return list == null;
	}

	/**
	 * Whether this is the collapsed list in its upright tab form.
	 */
	public boolean isUprightTab()
	{
		return list == null && header.height > header.width;
	}

	public int getRowHeight()
	{
		return rowHeight;
	}

	public int getVisibleRows()
	{
		return visibleRows;
	}

	public Rectangle getRow(int row)
	{
		return new Rectangle(list.x, list.y + row * rowHeight, list.width, rowHeight);
	}

	/**
	 * The strip down the right of the list that the scrollbar runs in, arrows and all, or null when everything fits.
	 *
	 * @param rowCount number of rows there are to scroll through
	 */
	public Rectangle getScrollbar(int rowCount)
	{
		if (list == null || rowCount <= visibleRows)
		{
			return null;
		}
		return new Rectangle(list.x + list.width - frame.scrollbarWidth, list.y, frame.scrollbarWidth, list.height);
	}

	/**
	 * The arrow at the top of the scrollbar, which scrolls up a row, or null when it has none: the flat one
	 * doesn't, nor does one too short for them.
	 */
	public Rectangle getScrollUp(int rowCount)
	{
		final Rectangle bar = getScrollbar(rowCount);
		return bar == null || !hasArrows(bar) ? null : new Rectangle(bar.x, bar.y, bar.width, frame.scrollArrow);
	}

	/**
	 * The arrow at the bottom of the scrollbar, which scrolls down a row, or null when it has none.
	 */
	public Rectangle getScrollDown(int rowCount)
	{
		final Rectangle bar = getScrollbar(rowCount);
		return bar == null || !hasArrows(bar) ? null
			: new Rectangle(bar.x, bar.y + bar.height - frame.scrollArrow, bar.width, frame.scrollArrow);
	}

	/**
	 * The part of the scrollbar that its thumb moves along, which is all of it but its arrows, or null when
	 * everything fits.
	 */
	public Rectangle getScrollTrack(int rowCount)
	{
		final Rectangle bar = getScrollbar(rowCount);
		if (bar == null || !hasArrows(bar))
		{
			return bar;
		}
		return new Rectangle(bar.x, bar.y + frame.scrollArrow, bar.width, bar.height - 2 * frame.scrollArrow);
	}

	private boolean hasArrows(Rectangle bar)
	{
		return frame.scrollArrow > 0 && bar.height >= 2 * frame.scrollArrow + SCROLL_THUMB_MIN;
	}

	/**
	 * The part of the scrollbar that stands for the rows in view, or null when everything fits.
	 *
	 * @param scroll index of the first visible row
	 */
	public Rectangle getScrollThumb(int rowCount, int scroll)
	{
		final Rectangle track = getScrollTrack(rowCount);
		if (track == null)
		{
			return null;
		}
		final int height = Math.max(SCROLL_THUMB_MIN, track.height * visibleRows / rowCount);
		final int maxScroll = rowCount - visibleRows;
		final int y = track.y + (track.height - height) * Math.max(0, Math.min(scroll, maxScroll)) / maxScroll;
		return new Rectangle(track.x, y, track.width, height);
	}

	/**
	 * The scroll position that puts the top of the scrollbar's thumb nearest to a height on the canvas, for
	 * dragging it.
	 */
	public int scrollAt(int rowCount, int thumbY)
	{
		final Rectangle track = getScrollTrack(rowCount);
		final Rectangle thumb = getScrollThumb(rowCount, 0);
		if (thumb == null || track.height <= thumb.height)
		{
			return 0;
		}
		final int maxScroll = rowCount - visibleRows;
		final int travel = track.height - thumb.height;
		final int offset = Math.max(0, Math.min(thumbY - track.y, travel));
		return (offset * maxScroll + travel / 2) / travel;
	}

	/**
	 * The visible row under the point, or -1.
	 */
	public int rowAt(Point p)
	{
		if (list == null || !list.contains(p))
		{
			return -1;
		}
		return (p.y - list.y) / rowHeight;
	}
}

package com.setuppicker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * State of the picker. Written from the client thread (setup data, rendering) and the AWT thread
 * (mouse and keyboard), so every access is synchronized and readers work from an immutable {@link View}.
 */
public class PickerModel
{
	/**
	 * Immutable snapshot of what the picker should currently show.
	 */
	public static final class View
	{
		private final List<PickerRow> rows;
		private final int total;
		private final String activeSetup;
		private final String query;
		private final boolean searchFocused;
		private final boolean paletteOpen;
		private final boolean sectionPages;
		private final boolean querySelected;
		private final int caret;
		private final int scroll;
		private final int selected;

		private final String activeBankTag;
		private final boolean mixed;
		private final boolean scrollbarDragged;
		private final boolean notesShown;

		private View(List<PickerRow> rows, int total, String activeSetup, String activeBankTag, boolean mixed, String query,
			boolean searchFocused, boolean paletteOpen, boolean sectionPages, int scroll, int selected, boolean querySelected,
			int caret, boolean scrollbarDragged, boolean notesShown)
		{
			this.notesShown = notesShown;
			this.scrollbarDragged = scrollbarDragged;
			this.activeBankTag = activeBankTag;
			this.mixed = mixed;
			this.caret = caret;
			this.querySelected = querySelected;
			this.sectionPages = sectionPages;
			this.rows = rows;
			this.total = total;
			this.activeSetup = activeSetup;
			this.query = query;
			this.searchFocused = searchFocused;
			this.paletteOpen = paletteOpen;
			this.scroll = scroll;
			this.selected = selected;
		}

		/**
		 * The setups matching the search in display order, each run of them under its section heading when
		 * they are grouped by section.
		 */
		public List<PickerRow> getRows()
		{
			return rows;
		}

		/**
		 * Number of setups before the search was applied.
		 */
		public int getTotal()
		{
			return total;
		}

		public String getActiveSetup()
		{
			return activeSetup;
		}

		/**
		 * Whether this is the setup that's open in Inventory Setups, or the bank tag that's open in the bank.
		 */
		public boolean isActive(SetupEntry setup)
		{
			return setup.getName().equals(setup.isBankTag() ? activeBankTag : activeSetup);
		}

		/**
		 * Whether both inventory setups and bank tags are listed, so that they need telling apart.
		 */
		public boolean isMixed()
		{
			return mixed;
		}

		/**
		 * Whether setups' notes are shown: a mark on those that have any, and the notes of the one pointed at.
		 */
		public boolean isNotesShown()
		{
			return notesShown;
		}

		/**
		 * Whether the scrollbar is being dragged with the mouse.
		 */
		public boolean isScrollbarDragged()
		{
			return scrollbarDragged;
		}

		public String getQuery()
		{
			return query;
		}

		/**
		 * Whether the whole search text is highlighted, after select all: the next thing typed replaces it.
		 */
		public boolean isQuerySelected()
		{
			return querySelected;
		}

		/**
		 * Where in the search text typing goes: the number of characters before the cursor.
		 */
		public int getCaret()
		{
			return caret;
		}

		public boolean isSearchFocused()
		{
			return searchFocused;
		}

		/**
		 * Whether the hotkey-opened popup is showing. It always has search focus while open.
		 */
		public boolean isPaletteOpen()
		{
			return paletteOpen;
		}

		/**
		 * Whether section headings can be picked, to open the section's own page or to go back from it.
		 */
		public boolean isSectionPages()
		{
			return sectionPages;
		}

		/**
		 * Index into {@link #getRows()} of the first visible row.
		 */
		public int getScroll()
		{
			return scroll;
		}

		/**
		 * Index into {@link #getRows()} of the keyboard selection, which is only on a heading if those can be
		 * picked. Only meaningful while searching.
		 */
		public int getSelected()
		{
			return selected;
		}
	}

	private List<PickerRow> rows = Collections.emptyList();
	private List<PickerRow> filtered = Collections.emptyList();
	private int total;
	private String activeSetup = "";
	private String activeBankTag = "";
	// A setup and a bank tag can be open at once. Which was opened later, for the popup to start on.
	private boolean bankTagOpenedLast;
	private boolean mixed;
	private boolean scrollbarDragged;
	private boolean showNotes;
	private String query = "";
	private boolean searchFocused;
	private boolean paletteOpen;
	private int scroll;
	private int selected;
	private int visibleRows = 1;
	private boolean fuzzySearch;
	private boolean querySelected;
	private int caret;
	private boolean startOnActiveSetup = true;
	// Set while the popup should keep its starting selection in view, until the user scrolls or searches
	private boolean revealSelection;
	private int scrollBeforePalette;
	private boolean sectionPages;
	// heading of the section whose page is showing, or null for the list of sections
	private PickerRow openSection;
	private PickerRow sectionBeforePalette;

	public synchronized View view()
	{
		return new View(filtered, total, activeSetup, activeBankTag, mixed, query, searchFocused, paletteOpen, isPaged(),
			scroll, selected, querySelected, caret, scrollbarDragged, showNotes);
	}

	/**
	 * Show each section on a page of its own, reached from a list of the sections, rather than everything in
	 * one list. Makes no difference when the setups aren't grouped by section.
	 */
	public synchronized void setSectionPages(boolean pages)
	{
		if (sectionPages != pages)
		{
			sectionPages = pages;
			openSection = null;
			sectionBeforePalette = null;
			refilter(true);
		}
	}

	/**
	 * Go to a section's page.
	 *
	 * @param header the section's heading, from the rows of a {@link View}
	 */
	public synchronized void openSection(PickerRow header)
	{
		if (isPaged() && header.isHeader())
		{
			openSection = header;
			query = "";
			caret = 0;
			refilter(true);
		}
	}

	/**
	 * Go back from a section's page to the list of sections, with the section that was open selected.
	 */
	public synchronized void closeSection()
	{
		final PickerRow closed = openSection;
		if (closed == null)
		{
			return;
		}
		openSection = null;
		query = "";
		caret = 0;
		refilter(true);
		for (int i = 0; i < filtered.size(); i++)
		{
			if (filtered.get(i).isHeader() && filtered.get(i).sameSection(closed))
			{
				moveSelection(i - selected);
				break;
			}
		}
	}

	/**
	 * List the setups as they are, without section headings.
	 */
	public synchronized void setSetups(List<SetupEntry> setups)
	{
		final List<PickerRow> newRows = new ArrayList<>(setups.size());
		for (SetupEntry setup : setups)
		{
			newRows.add(PickerRow.of(setup));
		}
		setRows(newRows, setups.size());
	}

	/**
	 * @param newRows  the setups to list. Every heading among them must be followed by at least one setup.
	 * @param newTotal number of setups there are, which is less than the setup rows when some are in several sections
	 */
	public synchronized void setRows(List<PickerRow> newRows, int newTotal)
	{
		rows = Collections.unmodifiableList(new ArrayList<>(newRows));
		total = newTotal;
		boolean setups = false;
		boolean bankTags = false;
		for (PickerRow row : rows)
		{
			if (!row.isHeader())
			{
				setups |= !row.getSetup().isBankTag();
				bankTags |= row.getSetup().isBankTag();
			}
		}
		mixed = setups && bankTags;
		// a reload (e.g. after a setup is edited) shouldn't move the list under the user
		refilter(false);
	}

	/**
	 * Whether to show the notes setups have in Inventory Setups.
	 */
	public synchronized void setShowNotes(boolean show)
	{
		showNotes = show;
	}

	/**
	 * Whether the popup opens with the selection on the setup that's already open, rather than at the top.
	 */
	public synchronized void setStartOnActiveSetup(boolean start)
	{
		startOnActiveSetup = start;
	}

	/**
	 * Whether a search that finds nothing as typed may match names that are a typo or a few letters away.
	 */
	public synchronized void setFuzzySearch(boolean fuzzy)
	{
		if (fuzzySearch != fuzzy)
		{
			fuzzySearch = fuzzy;
			refilter(false);
		}
	}

	public synchronized void setActiveSetup(String name)
	{
		final String active = name == null ? "" : name;
		if (!active.isEmpty() && !active.equals(activeSetup))
		{
			bankTagOpenedLast = false;
		}
		activeSetup = active;
	}

	/**
	 * @param name the bank tag that's open in the bank, or "" for none
	 */
	public synchronized void setActiveBankTag(String name)
	{
		final String active = name == null ? "" : name;
		if (!active.isEmpty() && !active.equals(activeBankTag))
		{
			bankTagOpenedLast = true;
		}
		activeBankTag = active;
	}

	private boolean isActive(SetupEntry setup)
	{
		return setup.getName().equals(setup.isBankTag() ? activeBankTag : activeSetup);
	}

	/**
	 * Told by the overlay how many rows fit, so scrolling can be clamped to it.
	 */
	public synchronized void setVisibleRows(int rows)
	{
		visibleRows = Math.max(1, rows);
		if (revealSelection && selected >= scroll + visibleRows)
		{
			scroll = selected - visibleRows + 1;
		}
		clamp();
	}

	public synchronized void scrollBy(int rows)
	{
		scrollTo(scroll + rows);
	}

	/**
	 * @param row the row to have at the top, as near as the list can be scrolled to it
	 */
	public synchronized void scrollTo(int row)
	{
		revealSelection = false;
		scroll = row;
		clamp();
	}

	/**
	 * Whether the scrollbar is being dragged, for it to be drawn as held.
	 */
	public synchronized void setScrollbarDragged(boolean dragged)
	{
		scrollbarDragged = dragged;
	}

	/**
	 * Focus or unfocus the search box of the list beside the bank.
	 */
	public synchronized void setSearchFocused(boolean focused)
	{
		searchFocused = focused;
		if (focused)
		{
			selected = 0;
			scroll = 0;
			clamp();
		}
	}

	/**
	 * Show the popup with an empty search, ready for typing.
	 */
	public synchronized void openPalette()
	{
		if (!paletteOpen)
		{
			scrollBeforePalette = query.isEmpty() ? scroll : 0;
			sectionBeforePalette = openSection;
		}
		openSection = null;
		paletteOpen = true;
		searchFocused = true;
		query = "";
		caret = 0;
		refilter(true);
		selectActiveSetup();
	}

	/**
	 * Start on the setup that's already open, when it's listed, so that it only takes Enter to close it. With
	 * both a setup and a bank tag open, it's whichever was opened later.
	 */
	private void selectActiveSetup()
	{
		if (!startOnActiveSetup)
		{
			return;
		}
		int open = -1;
		for (int i = 0; i < filtered.size(); i++)
		{
			final PickerRow row = filtered.get(i);
			if (row.isHeader() || !isActive(row.getSetup()))
			{
				continue;
			}
			if (row.getSetup().isBankTag() == bankTagOpenedLast)
			{
				open = i;
				break;
			}
			// the one opened earlier will do if the later one isn't listed
			if (open < 0)
			{
				open = i;
			}
		}
		if (open >= 0)
		{
			selected = open;
			// The popup's size isn't known until it is next drawn, so it is scrolled into view then
			revealSelection = true;
		}
	}

	/**
	 * Highlight the whole search text, so that typing replaces it and Backspace clears it.
	 */
	public synchronized void selectQuery()
	{
		querySelected = searchFocused && !query.isEmpty();
	}

	/**
	 * Move the cursor through the search text. After select all, it lands at the end moved towards.
	 *
	 * @param delta characters to move by; anything past either end stops there
	 */
	public synchronized void moveCaret(int delta)
	{
		if (querySelected)
		{
			querySelected = false;
			caret = delta < 0 ? 0 : query.length();
			return;
		}
		caret = (int) Math.max(0, Math.min((long) caret + delta, query.length()));
	}

	/**
	 * Delete the character after the cursor, or everything after select all.
	 */
	public synchronized void deleteForward()
	{
		if (querySelected)
		{
			query = "";
			caret = 0;
		}
		else if (caret < query.length())
		{
			query = query.substring(0, caret) + query.substring(caret + 1);
		}
		else
		{
			return;
		}
		refilter(true);
	}

	public synchronized void typeChar(char c)
	{
		if (querySelected)
		{
			query = "";
			caret = 0;
		}
		query = query.substring(0, caret) + c + query.substring(caret);
		caret++;
		refilter(true);
	}

	public synchronized void backspace()
	{
		if (!query.isEmpty())
		{
			if (querySelected)
			{
				query = "";
				caret = 0;
			}
			else if (caret > 0)
			{
				query = query.substring(0, caret - 1) + query.substring(caret);
				caret--;
			}
			else
			{
				// at the start of the text: nothing before the cursor to delete
				return;
			}
			refilter(true);
		}
		else
		{
			// nothing left to delete: back out of the section's page
			closeSection();
		}
	}

	public synchronized void moveSelection(int delta)
	{
		final int target = Math.max(0, Math.min(selected + delta, filtered.size() - 1));
		// going up, step over a heading to the setup above it. Going down is clamp's job.
		selected = isSkipped(target) && delta < 0 && target > 0 ? target - 1 : target;
		clamp();
		// keep the selection on screen, along with its heading when it's the first of a section
		if (selected < scroll)
		{
			scroll = isSkipped(selected - 1) && visibleRows > 1 ? selected - 1 : selected;
		}
		else if (selected >= scroll + visibleRows)
		{
			scroll = selected - visibleRows + 1;
		}
	}

	/**
	 * Move the selection by whole pages of visible rows.
	 */
	public synchronized void pageSelection(int pages)
	{
		moveSelection(pages * visibleRows);
	}

	/**
	 * The setup the keyboard selection is on, or null when nothing matches the search.
	 */
	public synchronized SetupEntry getSelectedSetup()
	{
		return selected < filtered.size() ? filtered.get(selected).getSetup() : null;
	}

	/**
	 * The row the keyboard selection is on, or null when nothing is listed.
	 */
	public synchronized PickerRow getSelectedRow()
	{
		return selected < filtered.size() ? filtered.get(selected) : null;
	}

	/**
	 * Drop the search text and focus and close the popup, e.g. after opening a setup.
	 */
	public synchronized void resetSearch()
	{
		// Back to the full list. If it was already showing, as when a setup is clicked in the list beside
		// the bank, it stays scrolled where it was.
		final boolean wasFiltered = !query.isEmpty();
		searchFocused = false;
		query = "";
		caret = 0;
		if (paletteOpen)
		{
			openSection = sectionBeforePalette;
		}
		refilter(wasFiltered);
		if (paletteOpen)
		{
			// the popup scrolls and changes page on its own; put the list beside the bank back where it was left
			paletteOpen = false;
			scroll = scrollBeforePalette;
			clamp();
		}
	}

	/**
	 * @param resetPosition go back to the top, for when what's listed has changed because of the search
	 */
	private void refilter(boolean resetPosition)
	{
		// a reload of the setups leaves the highlight alone; anything that changed the search has used it up
		querySelected &= !resetPosition && !query.isEmpty();
		revealSelection = false;
		final List<PickerRow> page = isPaged() ? page() : null;
		if (page != null)
		{
			filtered = page;
		}
		else if (query.isEmpty())
		{
			filtered = rows;
		}
		else
		{
			final String needle = query.toLowerCase(Locale.ROOT);
			List<PickerRow> matches = match(needle, SetupMatcher.Tier.EXACT);
			if (fuzzySearch)
			{
				// Only when the search would otherwise find nothing: allow for a typo, then for letters left out
				if (matches.isEmpty())
				{
					matches = match(needle, SetupMatcher.Tier.TYPO);
				}
				if (matches.isEmpty())
				{
					matches = match(needle, SetupMatcher.Tier.SUBSEQUENCE);
				}
			}
			filtered = Collections.unmodifiableList(matches);
		}
		if (resetPosition)
		{
			// start on the first setup rather than on its heading, even where headings can be picked
			selected = filtered.size() > 1 && filtered.get(0).isHeader() && !filtered.get(1).isHeader() ? 1 : 0;
			scroll = 0;
		}
		clamp();
	}

	/**
	 * Whether sections are being shown as pages: they have to be both wanted and there.
	 */
	private boolean isPaged()
	{
		return sectionPages && !rows.isEmpty() && rows.get(0).isHeader();
	}

	/**
	 * What to list when sections are pages, or null when it's the same as when they aren't: a search across
	 * all of them.
	 */
	private List<PickerRow> page()
	{
		final String needle = query.toLowerCase(Locale.ROOT);
		final List<PickerRow> page = new ArrayList<>();
		if (openSection == null)
		{
			if (!query.isEmpty())
			{
				return null;
			}
			// the list of sections
			for (PickerRow row : rows)
			{
				if (row.isHeader())
				{
					page.add(row);
				}
			}
			return Collections.unmodifiableList(page);
		}

		boolean inSection = false;
		for (PickerRow row : rows)
		{
			if (row.isHeader())
			{
				inSection = row.sameSection(openSection);
				if (inSection)
				{
					page.add(PickerRow.backFrom(row));
				}
			}
			else if (inSection && row.getSetup().getName().toLowerCase(Locale.ROOT).contains(needle))
			{
				page.add(row);
			}
		}
		if (page.isEmpty())
		{
			// the section has gone, or has no setups left
			openSection = null;
			return page();
		}
		return Collections.unmodifiableList(page);
	}

	private List<PickerRow> match(String needle, SetupMatcher.Tier tier)
	{
		final List<PickerRow> matches = new ArrayList<>();
		// the heading of the section being gone through, until one of its setups matches and it gets listed
		PickerRow pendingHeader = null;
		boolean sectionMatches = false;
		for (PickerRow row : rows)
		{
			if (row.isHeader())
			{
				pendingHeader = row;
				// a section's name finds all of its setups
				sectionMatches = !row.isBuiltIn()
					&& SetupMatcher.matches(row.getSectionName().toLowerCase(Locale.ROOT), needle, tier);
			}
			else if (sectionMatches || SetupMatcher.matches(row.getSetup().getName().toLowerCase(Locale.ROOT), needle, tier))
			{
				if (pendingHeader != null)
				{
					matches.add(pendingHeader);
					pendingHeader = null;
				}
				matches.add(row);
			}
		}
		return matches;
	}

	private void clamp()
	{
		scroll = Math.max(0, Math.min(scroll, filtered.size() - visibleRows));
		selected = Math.max(0, Math.min(selected, filtered.size() - 1));
		if (isSkipped(selected))
		{
			// a heading always has a setup below it
			selected++;
		}
	}

	/**
	 * Whether the row is a heading that the selection can't rest on.
	 */
	private boolean isSkipped(int index)
	{
		return !isPaged() && index >= 0 && index < filtered.size() && filtered.get(index).isHeader();
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

/**
 * Draws the picker. Has no dependency on the game client so it can be rendered in tests.
 */
public final class PickerPainter
{
	private static final Color BORDER_OUTER = new Color(14, 13, 15);
	private static final Color FIELD_BACKGROUND = new Color(0, 0, 0, 110);
	private static final Color ROW_HOVER = new Color(255, 255, 255, 28);
	private static final Color SECTION_BACKGROUND = new Color(0, 0, 0, 60);
	private static final Color FAVORITE = new Color(255, 215, 0);
	private static final Color SCROLLBAR = new Color(120, 110, 90);
	private static final Color SCROLLBAR_HOVER = new Color(160, 148, 120);
	private static final Color SCROLLBAR_TRACK = new Color(0, 0, 0, 70);
	private static final Color SHADOW = Color.BLACK;

	static final int ICON_WIDTH = 18;
	static final int ICON_HEIGHT = 16;
	private static final int STAR_SIZE = 7;
	private static final int CLOCK_SIZE = 9;
	private static final int SOURCE_SIZE = 9;
	private static final int NOTE_WIDTH = 7;
	private static final int NOTE_HEIGHT = 9;
	private static final int NOTES_PADDING = 6;
	private static final int NOTES_MAX_LINES = 8;
	private static final int NOTES_WIDTH = 190;
	private static final int SECTION_ARROW_WIDTH = 5;
	// lines of pixels from an arrowhead's flat side to its point
	private static final int ARROW_DEPTH = 5;

	// The marks on rows, a # for each pixel
	private static final String[] STAR = {
		"...#...",
		"..###..",
		"#######",
		".#####.",
		"..###..",
		".##.##.",
		".#...#.",
	};
	private static final String[] CLOCK = {
		"...###...",
		".##...##.",
		".#..#..#.",
		"#...#...#",
		"#...###.#",
		"#.......#",
		".#.....#.",
		".##...##.",
		"...###...",
	};
	private static final String[] NOTE = {
		"#######",
		"#.....#",
		"#.....#",
		"#.###.#",
		"#.....#",
		"#.###.#",
		"#.....#",
		"#.....#",
		"#######",
	};
	// pointing left, with the hole for its string at the point
	private static final String[] TAG = {
		".........",
		"...######",
		"..#######",
		".########",
		"###.#####",
		".########",
		"..#######",
		"...######",
	};
	// six dots, for something that can be taken hold of
	private static final String[] GRIP = {
		"##..##",
		"##..##",
		"......",
		"......",
		"##..##",
		"##..##",
		"......",
		"......",
		"##..##",
		"##..##",
	};
	// head, shoulders and arms, body, legs
	private static final String[] PERSON = {
		"...###...",
		"...###...",
		"...###...",
		".#######.",
		".#.###.#.",
		".#.###.#.",
		"...###...",
		"...#.#...",
		"...#.#...",
	};

	private final PickerTheme theme;
	private final String title;
	private final PickerSkin skin;

	public PickerPainter(PickerTheme theme)
	{
		this(theme, "Setups");
	}

	/**
	 * @param title what the title bar calls the things listed
	 */
	public PickerPainter(PickerTheme theme, String title)
	{
		this(theme, title, null);
	}

	/**
	 * @param skin the game's sprites to draw the frame, search box and scrollbar with, laid out for
	 *             {@link PickerLayout.Frame#GAME}, or null to draw them in the theme's colors
	 */
	public PickerPainter(PickerTheme theme, String title, PickerSkin skin)
	{
		this.theme = theme;
		this.title = title;
		this.skin = skin;
	}

	/**
	 * @param mouse  mouse position on the canvas, or null
	 * @param icons  a setup's icon, or null to draw no icons. May return null for an image that isn't ready.
	 *               Images of the icon size or smaller, or a pixel larger all round, are drawn pixel for pixel in
	 *               the middle of its place; larger ones are stretched to it.
	 * @param status message for the empty list when there are no setups at all
	 */
	public void paint(Graphics2D g, PickerLayout layout, PickerModel.View view, Point mouse,
		Function<SetupEntry, BufferedImage> icons, Font font, String status)
	{
		prepare(g);
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();

		final Rectangle bounds = layout.getBounds();
		if (skin != null)
		{
			skin.paintFrame(g, bounds, layout.getDivider());
		}
		else
		{
			g.setColor(theme.getBackground());
			g.fill(bounds);
		}

		paintHeader(g, fm, layout, view, mouse);

		if (!layout.isCollapsed())
		{
			paintSearch(g, fm, layout.getSearch(), view);
			paintList(g, fm, layout, view, mouse, icons, status);
		}
		if (layout.isPalette())
		{
			final SetupEntry selected = view.getSelected() < view.getRows().size() ? view.getRows().get(view.getSelected()).getSetup() : null;
			// picking the bank tag that's already open leaves it open, as clicking its tab does
			final boolean closes = selected != null && !selected.isBankTag() && view.isActive(selected);
			text(g, truncate(fm, "Up/Down: move   Enter: " + (closes ? "close" : "open") + "   Esc: cancel",
				layout.getFooter().width - 8), layout.getFooter().x + 4, baseline(fm, layout.getFooter()), theme.getMutedText());
		}

		if (skin == null)
		{
			paintBorder(g, bounds);
		}
	}

	private void paintBorder(Graphics2D g, Rectangle bounds)
	{
		g.setColor(theme.getBorder());
		g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
		g.setColor(BORDER_OUTER);
		g.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
	}

	private void paintHeader(Graphics2D g, FontMetrics fm, PickerLayout layout, PickerModel.View view, Point mouse)
	{
		final Rectangle header = layout.getTitle();
		// on the game's backing the title sits straight on the background, as the bank's does
		if (skin == null)
		{
			g.setColor(theme.getHeader());
			g.fill(header);
		}
		final boolean hovered = !layout.isPalette() && mouse != null && layout.getHeader().contains(mouse);
		if (hovered)
		{
			g.setColor(ROW_HOVER);
			g.fill(header);
		}

		g.setColor(theme.getAccent());
		final String counted = view.getTotal() > 0 ? title + " (" + view.getTotal() + ")" : title;
		if (layout.isUprightTab())
		{
			paintCollapsedTab(g, fm, header, counted);
			return;
		}
		if (layout.isPalette())
		{
			text(g, counted, header.x + 7, baseline(fm, header), theme.getAccent());
			return;
		}
		// a grip, for the list beside the bank being something that can be dragged by its title bar
		mark(g, GRIP, header.x + 5, header.y + header.height / 2 - 5, hovered ? theme.getAccent() : theme.getMutedText());
		text(g, counted, header.x + 16, baseline(fm, header), theme.getAccent());

		// collapse arrow: points down when open, right when collapsed
		final int cx = header.x + header.width - 11;
		final int cy = header.y + header.height / 2;
		if (layout.isCollapsed())
		{
			arrowhead(g, cx - 2, cy, 1, 0, theme.getAccent());
		}
		else
		{
			arrowhead(g, cx, cy - 2, 0, 1, theme.getAccent());
		}
	}

	/**
	 * The collapsed list in its upright form: a vertical tab with the expand arrow at the top and the title reading upwards.
	 */
	private void paintCollapsedTab(Graphics2D g, FontMetrics fm, Rectangle tab, String title)
	{
		final int arrowSpace = 16;
		final int cx = tab.x + tab.width / 2;
		final int cy = tab.y + arrowSpace / 2 + 2;
		arrowhead(g, cx - 2, cy, 1, 0, theme.getAccent());

		// Turned a quarter turn about the tab's bottom left corner, x runs up the tab and y across it
		final AffineTransform upright = g.getTransform();
		final int bottom = tab.y + tab.height;
		g.rotate(-Math.PI / 2, tab.x, bottom);
		final int across = (tab.width - fm.getAscent() - fm.getDescent()) / 2 + fm.getAscent();
		// the shadow still falls down and to the right on screen, which here is back along x and across y
		text(g, truncate(fm, title, tab.height - arrowSpace - 12), tab.x + 7, bottom + across, theme.getAccent(), -1, 1);
		g.setTransform(upright);
	}

	private void paintSearch(Graphics2D g, FontMetrics fm, Rectangle search, PickerModel.View view)
	{
		if (skin != null)
		{
			skin.paintField(g, search, view.isSearchFocused());
		}
		else
		{
			g.setColor(FIELD_BACKGROUND);
			g.fill(search);
			g.setColor(view.isSearchFocused() ? theme.getAccent() : theme.getBorder());
			g.drawRect(search.x, search.y, search.width - 1, search.height - 1);
		}

		// clear of the stone outline's bevelled corners, with the game's sprites
		final int inset = skin != null ? 8 : 5;
		final int textX = search.x + inset;
		final int maxWidth = search.width - 2 * inset;
		if (view.getQuery().isEmpty() && !view.isSearchFocused())
		{
			text(g, "Search...", textX, baseline(fm, search), theme.getMutedText());
			return;
		}

		// A search too long for the box is shown from far enough in to keep the cursor in view
		final String query = view.getQuery();
		final int caret = Math.min(view.getCaret(), query.length());
		int start = 0;
		while (start < caret && fm.stringWidth(query.substring(start, caret)) > maxWidth - 4)
		{
			start++;
		}
		int end = query.length();
		while (end > caret && fm.stringWidth(query.substring(start, end)) > maxWidth - 4)
		{
			end--;
		}
		final String shown = query.substring(start, end);

		if (view.isQuerySelected())
		{
			g.setColor(theme.getActiveRow());
			g.fillRect(textX - 1, search.y + 3, fm.stringWidth(shown) + 2, search.height - 6);
		}
		text(g, shown, textX, baseline(fm, search), theme.getText());

		if (view.isSearchFocused() && System.currentTimeMillis() / 500 % 2 == 0)
		{
			final int caretX = textX + fm.stringWidth(query.substring(start, caret)) + (caret == start ? 0 : 1);
			g.setColor(SHADOW);
			g.drawLine(caretX + 1, search.y + 5, caretX + 1, search.y + search.height - 4);
			g.setColor(theme.getText());
			g.drawLine(caretX, search.y + 4, caretX, search.y + search.height - 5);
		}
	}

	private void paintList(Graphics2D g, FontMetrics fm, PickerLayout layout, PickerModel.View view, Point mouse,
		Function<SetupEntry, BufferedImage> icons, String status)
	{
		final Rectangle list = layout.getList();
		final List<PickerRow> rows = view.getRows();

		if (rows.isEmpty())
		{
			final String message = view.getTotal() > 0 ? "No matches" : status;
			text(g, truncate(fm, message, list.width - 8), list.x + 4, baseline(fm, list), theme.getMutedText());
			return;
		}

		final Rectangle scrollbar = layout.getScrollbar(rows.size());
		final int rowWidth = list.width - (scrollbar != null ? scrollbar.width + 2 : 0);

		for (int i = 0; i < layout.getVisibleRows(); i++)
		{
			final int index = view.getScroll() + i;
			if (index >= rows.size())
			{
				break;
			}
			final Rectangle row = layout.getRow(i);
			row.width = rowWidth;
			final boolean hovered = mouse != null && row.contains(mouse);
			final boolean selected = view.isSearchFocused() && index == view.getSelected();
			if (rows.get(index).isHeader())
			{
				paintSectionHeader(g, fm, row, rows.get(index), view.isSectionPages(), hovered, selected);
				continue;
			}
			final SetupEntry setup = rows.get(index).getSetup();

			final boolean active = view.isActive(setup);
			if (active)
			{
				g.setColor(theme.getActiveRow());
				g.fill(row);
			}
			if (hovered || selected)
			{
				g.setColor(ROW_HOVER);
				g.fill(row);
			}
			if (selected)
			{
				g.setColor(theme.getAccent());
				g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
			}

			int textX = row.x + 4;
			if (icons != null)
			{
				final BufferedImage icon = icons.apply(setup);
				if (icon != null)
				{
					final int iconX = row.x + 2;
					final int iconY = row.y + (row.height - ICON_HEIGHT) / 2;
					if (icon.getWidth() <= ICON_WIDTH + 2 && icon.getHeight() <= ICON_HEIGHT + 2)
					{
						// with the margin for its outline spilling into the row's padding
						g.drawImage(icon, iconX + (ICON_WIDTH - icon.getWidth()) / 2, iconY + (ICON_HEIGHT - icon.getHeight()) / 2, null);
					}
					else
					{
						g.drawImage(icon, iconX, iconY, ICON_WIDTH, ICON_HEIGHT, null);
					}
				}
				textX = row.x + 2 + ICON_WIDTH + 4;
			}

			int textRight = row.x + row.width - 4;
			// rightmost, so that the marks line up down the list
			if (view.isMixed())
			{
				textRight -= SOURCE_SIZE + 3;
				paintSource(g, textRight + 3, row.y + (row.height - SOURCE_SIZE) / 2, setup.isBankTag());
			}
			if (setup.isFavorite())
			{
				textRight -= STAR_SIZE + 3;
				paintStar(g, textRight + 3 + STAR_SIZE / 2, row.y + row.height / 2);
			}
			if (rows.get(index).isRecent())
			{
				textRight -= CLOCK_SIZE + 3;
				paintClock(g, textRight + 3 + CLOCK_SIZE / 2, row.y + row.height / 2);
			}
			if (view.isNotesShown() && !setup.getNotes().isEmpty())
			{
				textRight -= NOTE_WIDTH + 3;
				paintNote(g, textRight + 3, row.y + (row.height - NOTE_HEIGHT) / 2);
			}

			final Color color = setup.getDisplayColor() != null ? setup.getDisplayColor() : (active ? theme.getAccent() : theme.getText());
			text(g, truncate(fm, setup.getName(), textRight - textX), textX, baseline(fm, row), color);
		}

		if (scrollbar != null && skin != null)
		{
			skin.paintScrollbar(g, layout.getScrollTrack(rows.size()), layout.getScrollThumb(rows.size(), view.getScroll()),
				layout.getScrollUp(rows.size()), layout.getScrollDown(rows.size()));
		}
		else if (scrollbar != null)
		{
			g.setColor(SCROLLBAR_TRACK);
			g.fill(scrollbar);
			// it can be dragged, or clicked above or below to jump there
			g.setColor(view.isScrollbarDragged() || mouse != null && scrollbar.contains(mouse) ? SCROLLBAR_HOVER : SCROLLBAR);
			g.fill(layout.getScrollThumb(rows.size(), view.getScroll()));
		}
	}

	/**
	 * @param pickable the heading leads to the section's page, or back from it, so gets an arrow saying which
	 */
	private void paintSectionHeader(Graphics2D g, FontMetrics fm, Rectangle row, PickerRow header,
		boolean pickable, boolean hovered, boolean selected)
	{
		g.setColor(SECTION_BACKGROUND);
		g.fill(row);
		if (pickable && (hovered || selected))
		{
			g.setColor(ROW_HOVER);
			g.fill(row);
		}
		if (pickable && selected)
		{
			g.setColor(theme.getAccent());
			g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
		}

		// muted reads as disabled, which a heading that can be picked isn't
		final Color color = header.getSectionColor() != null ? header.getSectionColor() : (pickable ? theme.getText() : theme.getMutedText());
		final int cy = row.y + row.height / 2;
		int textX = row.x + 4;
		int right = row.x + row.width - 4;
		g.setColor(color);
		if (header.isBack())
		{
			paintArrow(g, textX, cy, -1, color);
			textX += SECTION_ARROW_WIDTH + 4;
		}
		else if (pickable)
		{
			right -= SECTION_ARROW_WIDTH;
			paintArrow(g, right, cy, 1, color);
			right -= 4;
		}

		final String name = truncate(fm, header.getSectionName(), right - textX);
		text(g, name, textX, baseline(fm, row), color);

		// rule filling the rest of the row
		final int ruleX = textX + fm.stringWidth(name) + 5;
		if (ruleX < right)
		{
			g.setColor(theme.getBorder());
			g.drawLine(ruleX, cy, right - 1, cy);
		}
	}

	/**
	 * A small arrowhead filling the section arrow's width from x, pointing right for a direction of 1 and left for -1.
	 */
	private void paintArrow(Graphics2D g, int x, int cy, int direction, Color color)
	{
		arrowhead(g, direction > 0 ? x : x + SECTION_ARROW_WIDTH - 1, cy, direction, 0, color);
	}

	/**
	 * An arrowhead, made of lines of 9, 7, 5, 3 and 1 pixels from its flat side to its point, which drawn pixel by
	 * pixel comes out even on both sides at this size, as a filled triangle doesn't.
	 *
	 * @param x  the middle of its flat side
	 * @param dx the way it points across: 1 for right, -1 for left, or 0 when it points up or down
	 * @param dy the way it points down: 1 for down, -1 for up, or 0 when it points left or right
	 */
	private static void arrowhead(Graphics2D g, int x, int y, int dx, int dy, Color color)
	{
		for (int pass = 0; pass < 2; pass++)
		{
			// shadow first, as for text
			final int offset = pass == 0 ? 1 : 0;
			g.setColor(pass == 0 ? SHADOW : color);
			for (int step = 0; step < ARROW_DEPTH; step++)
			{
				final int half = ARROW_DEPTH - 1 - step;
				if (dx != 0)
				{
					g.fillRect(x + dx * step + offset, y - half + offset, 1, 2 * half + 1);
				}
				else
				{
					g.fillRect(x - half + offset, y + dy * step + offset, 2 * half + 1, 1);
				}
			}
		}
	}

	/**
	 * Marks a setup that has notes: a page with a couple of lines of writing on it.
	 */
	private void paintNote(Graphics2D g, int x, int y)
	{
		mark(g, NOTE, x, y, theme.getMutedText());
	}

	/**
	 * Draws one of the little pictures that mark rows, pixel by pixel so that it is as crisp as the text beside it,
	 * and with the same shadow.
	 *
	 * @param picture rows of the picture, with a # for each pixel to draw
	 * @param x       left of the picture
	 * @param y       top of the picture
	 */
	private static void mark(Graphics2D g, String[] picture, int x, int y, Color color)
	{
		for (int pass = 0; pass < 2; pass++)
		{
			final int offset = pass == 0 ? 1 : 0;
			g.setColor(pass == 0 ? SHADOW : color);
			for (int row = 0; row < picture.length; row++)
			{
				for (int column = 0; column < picture[row].length(); column++)
				{
					if (picture[row].charAt(column) == '#')
					{
						g.fillRect(x + column + offset, y + row + offset, 1, 1);
					}
				}
			}
		}
	}

	/**
	 * Draws the notes of the setup under the mouse, or else of the one the keyboard selection is on, in a box
	 * beside the picker, level with the setup. Nothing is drawn when it has no notes, or when notes aren't shown.
	 *
	 * @param mouse      mouse position on the canvas, or null
	 * @param canvas     the area the box has to stay within
	 * @param preferLeft put the box to the left of the picker when there is room on both sides, as for the list
	 *                   that has the bank on its right. It goes on the other side when there's only room there.
	 */
	public void paintNotes(Graphics2D g, PickerLayout layout, PickerModel.View view, Point mouse, Font font,
		Rectangle canvas, boolean preferLeft)
	{
		if (!view.isNotesShown() || layout.isCollapsed())
		{
			return;
		}
		final List<PickerRow> rows = view.getRows();
		final int hovered = mouse == null ? -1 : layout.rowAt(mouse);
		final int index = hovered >= 0 ? view.getScroll() + hovered : (view.isSearchFocused() ? view.getSelected() : -1);
		final SetupEntry setup = index >= 0 && index < rows.size() ? rows.get(index).getSetup() : null;
		if (setup == null || setup.getNotes().isEmpty())
		{
			return;
		}

		prepare(g);
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();
		final Rectangle bounds = layout.getBounds();
		final int leftRoom = bounds.x - canvas.x;
		final int rightRoom = canvas.x + canvas.width - bounds.x - bounds.width;
		// clear of the game's thicker frame too, which goes round the room the text has rather than taking from it
		final int padding = Math.max(NOTES_PADDING, layout.getFrame().edge + 4);
		final int boxWidth = NOTES_WIDTH + 2 * (padding - NOTES_PADDING);
		final boolean left = leftRoom >= boxWidth && (preferLeft || rightRoom < boxWidth)
			// too narrow a canvas for it either way: whichever side has more of it
			|| rightRoom < boxWidth && leftRoom > rightRoom;
		final int width = Math.max(4 * padding, Math.min(boxWidth, left ? leftRoom : rightRoom));
		final List<String> lines = wrap(fm, setup.getNotes(), width - 2 * padding, NOTES_MAX_LINES);
		final int height = lines.size() * fm.getHeight() + 2 * padding;

		// sharing the picker's edge, or against the game's frame, and starting level with the setup unless that runs
		// off the bottom
		final int row = index - view.getScroll();
		final int level = row >= 0 && row < layout.getVisibleRows() ? layout.getRow(row).y : layout.getList().y;
		final int y = Math.max(canvas.y, Math.min(level, canvas.y + canvas.height - height));
		final int overlap = skin == null ? 1 : 0;
		final Rectangle box = new Rectangle(left ? bounds.x - width + overlap : bounds.x + bounds.width - overlap, y, width, height);

		if (skin != null)
		{
			skin.paintFrame(g, box, 0);
		}
		else
		{
			g.setColor(theme.getBackground());
			g.fill(box);
			paintBorder(g, box);
		}

		int baseline = box.y + padding + fm.getAscent();
		for (String line : lines)
		{
			text(g, line, box.x + padding, baseline, theme.getText());
			baseline += fm.getHeight();
		}
	}

	/**
	 * Breaks text into lines no wider than given, at spaces where it can, keeping the line breaks it has.
	 *
	 * @param maxLines the most lines to return. Text that would take more is cut short there with an ellipsis.
	 */
	static List<String> wrap(FontMetrics fm, String text, int maxWidth, int maxLines)
	{
		final List<String> lines = new ArrayList<>();
		for (String paragraph : text.replace("\r", "").replace('\t', ' ').split("\n"))
		{
			String line = "";
			for (String word : paragraph.trim().split(" +"))
			{
				// a word too long for a line of its own is broken wherever it has to be
				while (fm.stringWidth(word) > maxWidth && word.length() > 1)
				{
					if (!line.isEmpty())
					{
						lines.add(line);
						line = "";
					}
					int fits = 1;
					while (fits < word.length() && fm.stringWidth(word.substring(0, fits + 1)) <= maxWidth)
					{
						fits++;
					}
					lines.add(word.substring(0, fits));
					word = word.substring(fits);
				}
				final String longer = line.isEmpty() ? word : line + " " + word;
				if (fm.stringWidth(longer) <= maxWidth)
				{
					line = longer;
				}
				else
				{
					lines.add(line);
					line = word;
				}
			}
			lines.add(line);
		}
		if (lines.size() <= maxLines)
		{
			return lines;
		}
		final List<String> cut = new ArrayList<>(lines.subList(0, maxLines));
		String last = cut.get(maxLines - 1);
		while (!last.isEmpty() && fm.stringWidth(last + "...") > maxWidth)
		{
			last = last.substring(0, last.length() - 1);
		}
		cut.set(maxLines - 1, last + "...");
		return cut;
	}

	/**
	 * Marks a recently used setup: a clock face showing about three o'clock.
	 */
	private void paintClock(Graphics2D g, int cx, int cy)
	{
		mark(g, CLOCK, cx - CLOCK_SIZE / 2, cy - CLOCK_SIZE / 2, theme.getMutedText());
	}

	/**
	 * Marks where a row is from when both are listed: a luggage tag for a bank tag, and for an inventory setup
	 * a little person, after the icon of Inventory Setups.
	 *
	 * @param x left of the mark
	 * @param y top of the mark
	 */
	private void paintSource(Graphics2D g, int x, int y, boolean bankTag)
	{
		mark(g, bankTag ? TAG : PERSON, x, y, theme.getMutedText());
	}

	private void paintStar(Graphics2D g, int cx, int cy)
	{
		mark(g, STAR, cx - STAR_SIZE / 2, cy - STAR_SIZE / 2, FAVORITE);
	}

	/**
	 * Sets the graphics up to draw as the game draws its interfaces. Overlays are given antialiasing, which blurs
	 * the RuneScape fonts' pixels at their edges and softens small shapes, and the game draws both without. The
	 * overlay renderer puts the hints back after each overlay, so this goes no further than the picker.
	 */
	static void prepare(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
	}

	/**
	 * Draws text as the game draws it on its interfaces: over a black copy of itself a pixel down and to the right.
	 */
	private static void text(Graphics2D g, String text, int x, int y, Color color)
	{
		text(g, text, x, y, color, 1, 1);
	}

	/**
	 * @param shadowX where the shadow goes from the text, in the graphics' own coordinates
	 */
	private static void text(Graphics2D g, String text, int x, int y, Color color, int shadowX, int shadowY)
	{
		g.setColor(SHADOW);
		g.drawString(text, x + shadowX, y + shadowY);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static int baseline(FontMetrics fm, Rectangle box)
	{
		return box.y + (box.height - fm.getAscent() - fm.getDescent()) / 2 + fm.getAscent();
	}

	private static String truncate(FontMetrics fm, String text, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		final String ellipsis = "...";
		String cut = text;
		while (!cut.isEmpty() && fm.stringWidth(cut + ellipsis) > maxWidth)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + ellipsis;
	}
}

package com.setuppicker;

import java.awt.Color;

/**
 * One line of the picker's list: a setup, or the heading of the section the setups below it belong to.
 */
public final class PickerRow
{
	/**
	 * Heading for the setups that aren't in any section.
	 */
	public static final PickerRow UNASSIGNED = new PickerRow(null, "Unassigned", null, false, false, 1);

	/**
	 * Heading for the recently used setups, when the list is in sections.
	 */
	public static final PickerRow RECENT = new PickerRow(null, "Recent", null, false, false, 2);

	/**
	 * Heading for the bank tags, which have no sections of their own, when the list is in sections.
	 */
	public static final PickerRow BANK_TAGS = new PickerRow(null, "Bank tags", null, false, false, 3);

	/**
	 * Heading for all the setups, when both setups and bank tags are listed and grouped but no sections are in use.
	 */
	public static final PickerRow SETUPS = new PickerRow(null, "Inventory Setups", null, false, false, 4);

	private final SetupEntry setup;
	private final String sectionName;
	private final Color sectionColor;
	private final boolean back;
	private final boolean recent;

	// 0 for a setup or a section of the user's; otherwise which of the headings above this is, or leads back from
	private final int builtIn;

	private PickerRow(SetupEntry setup, String sectionName, Color sectionColor, boolean back, boolean recent, int builtIn)
	{
		this.recent = recent;
		this.builtIn = builtIn;
		this.setup = setup;
		this.sectionName = sectionName;
		this.sectionColor = sectionColor;
		this.back = back;
	}

	public static PickerRow of(SetupEntry setup)
	{
		return new PickerRow(setup, null, null, false, false, 0);
	}

	/**
	 * A setup listed at the top for having been used recently.
	 */
	public static PickerRow recent(SetupEntry setup)
	{
		return new PickerRow(setup, null, null, false, true, 0);
	}

	public static PickerRow header(SetupSection section)
	{
		return new PickerRow(null, section.getName(), section.getDisplayColor(), false, false, 0);
	}

	/**
	 * The heading at the top of a section's own page, which leads back to the list of sections.
	 */
	public static PickerRow backFrom(PickerRow header)
	{
		return new PickerRow(null, header.sectionName, header.sectionColor, true, false, header.builtIn);
	}

	public boolean isHeader()
	{
		return setup == null;
	}

	/**
	 * Whether this setup is listed here for having been used recently.
	 */
	public boolean isRecent()
	{
		return recent;
	}

	/**
	 * Whether this heading is one of the picker's own rather than a section from Inventory Setups.
	 */
	public boolean isBuiltIn()
	{
		return builtIn != 0;
	}

	/**
	 * Whether this is the heading of a section's page, for going back to the list of sections.
	 */
	public boolean isBack()
	{
		return back;
	}

	/**
	 * Whether this heading and the other are for the same section.
	 */
	boolean sameSection(PickerRow other)
	{
		// a section the user happened to name "Unassigned", "Recent" or "Bank tags" is not the built-in one
		return builtIn == other.builtIn && sectionName.equals(other.sectionName);
	}

	/**
	 * The setup on this row, or null for a heading.
	 */
	public SetupEntry getSetup()
	{
		return setup;
	}

	/**
	 * The section name of a heading, or null for a setup.
	 */
	public String getSectionName()
	{
		return sectionName;
	}

	/**
	 * The color the user gave the section in Inventory Setups, or null for none.
	 */
	public Color getSectionColor()
	{
		return sectionColor;
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.SpriteID;

/**
 * Draws the picker's chrome from the game's own interface sprites, so that it follows whatever Resource Packs or
 * Interface Styles has made of them: the bank's riveted steel frame and background, the stone outline of the
 * game's input boxes, and the game's scrollbar. Has no dependency on the game client so it can be rendered in tests.
 * <p>
 * Every sprite is used trimmed to its visible pixels and placed flush against the edge it belongs to. The cache
 * keeps an edge piece as a strip at an offset in a larger box, while a resource pack supplies it as an image of
 * the whole box; trimmed, both are the same strip.
 */
public final class PickerSkin
{
	/**
	 * Where the sprites come from.
	 */
	public interface Sprites
	{
		/**
		 * The visible pixels of a sprite as {@link #trim} leaves them, {@link #EMPTY} for one that is all
		 * see-through, or null when it can't be had.
		 */
		BufferedImage get(int id);
	}

	/**
	 * A sprite with nothing to show, which takes up no room and draws nothing.
	 */
	public static final BufferedImage EMPTY = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

	private static final int BACKGROUND = SpriteID.TRADEBACKING;
	private static final int FIELD = SpriteID.TRADEBACKING_DARK;
	private static final int TOP_LEFT = SpriteID.Steelborder.TOP_LEFT;
	private static final int TOP_RIGHT = SpriteID.Steelborder.TOP_RIGHT;
	private static final int BOTTOM_LEFT = SpriteID.Steelborder.BOTTOM_LEFT;
	private static final int BOTTOM_RIGHT = SpriteID.Steelborder.BOTTOM_RIGHT;
	private static final int TOP = SpriteID.Steelborder2.EDGE_TOP;
	private static final int RIGHT = SpriteID.Steelborder2.EDGE_RIGHT;
	private static final int BOTTOM = SpriteID.Miscgraphics.IRON_RIVETS_HORIZONTAL;
	private static final int LEFT = SpriteID.Miscgraphics.IRON_RIVETS_VERTICAL;
	private static final int DIVIDER = SpriteID.SteelborderDivider._0;
	private static final int ARROW_UP = SpriteID.ScrollbarV2.ARROW_UP;
	private static final int ARROW_DOWN = SpriteID.ScrollbarV2.ARROW_DOWN;
	private static final int THUMB_TOP = SpriteID.ScrollbarDraggerV2.TOP;
	private static final int THUMB_MIDDLE = SpriteID.ScrollbarDraggerV2.MIDDLE;
	private static final int THUMB_BOTTOM = SpriteID.ScrollbarDraggerV2.BOTTOM;
	private static final int TRACK = SpriteID.ScrollbarDraggerV2.TRACK;
	// The stone outline of a box, as round the equipment screen's buttons: corners, then edges, in the order
	// top left, top right, bottom left, bottom right, left, top, right, bottom. The focused box's is the
	// lighter one those buttons have under the mouse.
	private static final int[] FIELD_EDGES = {
		SpriteID.V2StoneButton.TOP_LEFT, SpriteID.V2StoneButton.TOP_RIGHT, SpriteID.V2StoneButton.BOTTOM_LEFT,
		SpriteID.V2StoneButton.BOTTOM_RIGHT, SpriteID.V2StoneButton.LEFT, SpriteID.V2StoneButton.TOP,
		SpriteID.V2StoneButton.RIGHT, SpriteID.V2StoneButton.BOTTOM,
	};
	private static final int[] FOCUSED_FIELD_EDGES = {
		SpriteID.V2StoneButtonIn.A_TOP_LEFT, SpriteID.V2StoneButtonIn.A_TOP_RIGHT, SpriteID.V2StoneButtonIn.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_RIGHT, SpriteID.V2StoneButtonIn.A_LEFT, SpriteID.V2StoneButtonIn.A_TOP,
		SpriteID.V2StoneButtonIn.A_RIGHT, SpriteID.V2StoneButtonIn.A_BOTTOM,
	};
	private static final int[] SPRITES = {
		BACKGROUND, FIELD, TOP_LEFT, TOP_RIGHT, BOTTOM_LEFT, BOTTOM_RIGHT, TOP, RIGHT, BOTTOM, LEFT, DIVIDER,
		ARROW_UP, ARROW_DOWN, THUMB_TOP, THUMB_MIDDLE, THUMB_BOTTOM, TRACK,
	};

	// How far the field's darker backing is inset from its outline's outer edge
	private static final int FIELD_INSET = 2;
	// Frames of a few sizes are kept, for the popup, the list beside the bank and their boxes of notes
	private static final int FRAMES_KEPT = 6;

	private final Sprites sprites;
	private final Map<Long, BufferedImage> frames = new LinkedHashMap<Long, BufferedImage>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, BufferedImage> eldest)
		{
			return size() > FRAMES_KEPT;
		}
	};

	public PickerSkin(Sprites sprites)
	{
		this.sprites = sprites;
	}

	/**
	 * Whether every sprite this draws with can be had. If one can't, the picker is better drawn in its colors.
	 * Every sprite is asked for, rather than stopping at the first that can't be had, so that the game is asked to
	 * load all of them at once.
	 */
	public boolean isComplete()
	{
		boolean complete = true;
		for (int id : SPRITES)
		{
			complete &= sprites.get(id) != null;
		}
		for (int i = 0; i < FIELD_EDGES.length; i++)
		{
			complete &= sprites.get(FIELD_EDGES[i]) != null;
			complete &= sprites.get(FOCUSED_FIELD_EDGES[i]) != null;
		}
		return complete;
	}

	/**
	 * The average color of the background, for the colors that are worked out from the background's, or the
	 * color theme's own background when the background is see-through.
	 */
	public Color getBackground()
	{
		return average(sprites.get(BACKGROUND), PickerTheme.DEFAULT_BACKGROUND);
	}

	/**
	 * The average color of the darker backing of input boxes.
	 */
	public Color getField()
	{
		return average(sprites.get(FIELD), PickerTheme.DEFAULT_HEADER);
	}

	/**
	 * Draws the background and the frame around it.
	 *
	 * @param divider how far down the bounds to put a divider across, under a title, or 0 for none
	 */
	public void paintFrame(Graphics2D g, Rectangle bounds, int divider)
	{
		// Composed once for each size, since it's the same every frame
		final long key = (long) bounds.width << 40 | (long) bounds.height << 20 | divider;
		BufferedImage frame = frames.get(key);
		if (frame == null)
		{
			frame = composeFrame(bounds.width, bounds.height, divider);
			frames.put(key, frame);
		}
		g.drawImage(frame, bounds.x, bounds.y, null);
	}

	/**
	 * The bank's steel frame laid out round a box of this size, on its background.
	 */
	private BufferedImage composeFrame(int width, int height, int divider)
	{
		final BufferedImage frame = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = frame.createGraphics();
		try
		{
			tile(g, BACKGROUND, 0, 0, width, height);
			final int left = width(LEFT);
			final int right = width(RIGHT);
			if (divider > 0)
			{
				tile(g, DIVIDER, left, divider, width - left - right, height(DIVIDER));
			}

			final int bottom = height(BOTTOM);
			tile(g, TOP, width(TOP_LEFT), 0, width - width(TOP_LEFT) - width(TOP_RIGHT), height(TOP));
			tile(g, BOTTOM, width(BOTTOM_LEFT), height - bottom, width - width(BOTTOM_LEFT) - width(BOTTOM_RIGHT), bottom);
			tile(g, LEFT, 0, height(TOP_LEFT), left, height - height(TOP_LEFT) - height(BOTTOM_LEFT));
			tile(g, RIGHT, width - right, height(TOP_RIGHT), right, height - height(TOP_RIGHT) - height(BOTTOM_RIGHT));

			// Each corner kept to its own quarter, so that on a box too small for them they meet rather than overlap
			final int midX = width / 2;
			final int midY = height / 2;
			corner(g, TOP_LEFT, 0, 0, new Rectangle(0, 0, midX, midY));
			corner(g, TOP_RIGHT, width - width(TOP_RIGHT), 0, new Rectangle(midX, 0, width - midX, midY));
			corner(g, BOTTOM_LEFT, 0, height - height(BOTTOM_LEFT), new Rectangle(0, midY, midX, height - midY));
			corner(g, BOTTOM_RIGHT, width - width(BOTTOM_RIGHT), height - height(BOTTOM_RIGHT),
				new Rectangle(midX, midY, width - midX, height - midY));
		}
		finally
		{
			g.dispose();
		}
		return frame;
	}

	private void corner(Graphics2D g, int id, int x, int y, Rectangle quarter)
	{
		final Shape clip = g.getClip();
		g.clip(quarter);
		draw(g, id, x, y);
		g.setClip(clip);
	}

	/**
	 * Draws an input box: the darker backing inside a stone outline.
	 */
	public void paintField(Graphics2D g, Rectangle box, boolean focused)
	{
		tile(g, FIELD, box.x + FIELD_INSET, box.y + FIELD_INSET, box.width - 2 * FIELD_INSET, box.height - 2 * FIELD_INSET);
		final int[] edges = focused ? FOCUSED_FIELD_EDGES : FIELD_EDGES;
		final int topLeft = edges[0];
		final int topRight = edges[1];
		final int bottomLeft = edges[2];
		final int bottomRight = edges[3];
		final int right = width(edges[6]);
		final int bottom = height(edges[7]);
		final int x = box.x;
		final int y = box.y;
		final int x2 = box.x + box.width;
		final int y2 = box.y + box.height;
		tile(g, edges[4], x, y + height(topLeft), width(edges[4]), box.height - height(topLeft) - height(bottomLeft));
		tile(g, edges[5], x + width(topLeft), y, box.width - width(topLeft) - width(topRight), height(edges[5]));
		tile(g, edges[6], x2 - right, y + height(topRight), right, box.height - height(topRight) - height(bottomRight));
		tile(g, edges[7], x + width(bottomLeft), y2 - bottom, box.width - width(bottomLeft) - width(bottomRight), bottom);
		draw(g, topLeft, x, y);
		draw(g, topRight, x2 - width(topRight), y);
		draw(g, bottomLeft, x, y2 - height(bottomLeft));
		draw(g, bottomRight, x2 - width(bottomRight), y2 - height(bottomRight));
	}

	/**
	 * Draws the game's scrollbar.
	 *
	 * @param track the part the thumb moves along
	 * @param up    the arrow above it, or null for none
	 * @param down  the arrow below it, or null for none
	 */
	public void paintScrollbar(Graphics2D g, Rectangle track, Rectangle thumb, Rectangle up, Rectangle down)
	{
		tile(g, TRACK, track.x, track.y, track.width, track.height);
		if (up != null)
		{
			centre(g, ARROW_UP, up);
		}
		if (down != null)
		{
			centre(g, ARROW_DOWN, down);
		}
		final int top = height(THUMB_TOP);
		final int bottom = height(THUMB_BOTTOM);
		tile(g, THUMB_MIDDLE, thumb.x, thumb.y + top, thumb.width, thumb.height - top - bottom);
		tile(g, THUMB_TOP, thumb.x, thumb.y, thumb.width, top);
		tile(g, THUMB_BOTTOM, thumb.x, thumb.y + thumb.height - bottom, thumb.width, bottom);
	}

	/**
	 * How wide a sprite is, which for one with nothing to show is nothing.
	 */
	private int width(int id)
	{
		final BufferedImage sprite = sprites.get(id);
		return sprite == EMPTY ? 0 : sprite.getWidth();
	}

	private int height(int id)
	{
		final BufferedImage sprite = sprites.get(id);
		return sprite == EMPTY ? 0 : sprite.getHeight();
	}

	private void draw(Graphics2D g, int id, int x, int y)
	{
		final BufferedImage sprite = sprites.get(id);
		if (sprite != EMPTY)
		{
			g.drawImage(sprite, x, y, null);
		}
	}

	/**
	 * Draws a sprite in the middle of a box, pixel for pixel, as a pack's smaller arrow is meant to be.
	 */
	private void centre(Graphics2D g, int id, Rectangle box)
	{
		draw(g, id, box.x + (box.width - width(id)) / 2, box.y + (box.height - height(id)) / 2);
	}

	/**
	 * Repeats a sprite across an area from its top left corner, cut off at the area's edges, as the game tiles one.
	 */
	private void tile(Graphics2D g, int id, int x, int y, int width, int height)
	{
		final BufferedImage sprite = sprites.get(id);
		if (sprite == EMPTY || width <= 0 || height <= 0)
		{
			return;
		}
		for (int tileY = y; tileY < y + height; tileY += sprite.getHeight())
		{
			final int h = Math.min(sprite.getHeight(), y + height - tileY);
			for (int tileX = x; tileX < x + width; tileX += sprite.getWidth())
			{
				final int w = Math.min(sprite.getWidth(), x + width - tileX);
				g.drawImage(sprite, tileX, tileY, tileX + w, tileY + h, 0, 0, w, h, null);
			}
		}
	}

	/**
	 * The part of an image that isn't see-through, or {@link #EMPTY} for an image that all is. A pack can leave a
	 * sprite blank on purpose, such as a scrollbar with no track, and then there is simply nothing to draw.
	 */
	static BufferedImage trim(BufferedImage image)
	{
		int left = image.getWidth();
		int top = image.getHeight();
		int right = -1;
		int bottom = -1;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (image.getRGB(x, y) >>> 24 != 0)
				{
					left = Math.min(left, x);
					right = Math.max(right, x);
					top = Math.min(top, y);
					bottom = Math.max(bottom, y);
				}
			}
		}
		if (right < 0)
		{
			return EMPTY;
		}
		final BufferedImage trimmed = new BufferedImage(right - left + 1, bottom - top + 1, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = trimmed.createGraphics();
		g.drawImage(image, -left, -top, null);
		g.dispose();
		return trimmed;
	}

	/**
	 * The average color of an image's visible pixels, or the fallback when it has none.
	 */
	private static Color average(BufferedImage image, Color fallback)
	{
		long red = 0;
		long green = 0;
		long blue = 0;
		long count = 0;
		for (int y = 0; image != EMPTY && y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				final int pixel = image.getRGB(x, y);
				if (pixel >>> 24 != 0)
				{
					red += pixel >> 16 & 0xff;
					green += pixel >> 8 & 0xff;
					blue += pixel & 0xff;
					count++;
				}
			}
		}
		return count == 0 ? fallback : new Color((int) (red / count), (int) (green / count), (int) (blue / count));
	}
}

package com.setuppicker;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * What the lists are drawn in: the colors of the Colors settings or, with Match resource pack on, the game's own
 * interface sprites. Shared by the lists and the spellbook line, and only worked out again when something it
 * depends on changes.
 * <p>
 * Client thread only, but for {@link #onConfigChanged}.
 */
@Singleton
public class PickerStyle
{
	// While the game's sprites can't all be had they are tried for again every client tick at first, as they load
	// at startup, and then only every so often, for one the game may never have
	private static final long STARTUP_MILLIS = 5000;
	private static final long RETRY_MILLIS = 2000;

	private final SetupPickerConfig config;
	private final GameSprites sprites;

	// Set from any thread when a setting changes, and acted on by the next refresh
	private volatile boolean stale = true;
	private PickerTheme theme;
	// read by the mouse too, for the room the list's frame takes while it is dragged
	private volatile PickerSkin skin;
	// what the skin was made from
	private int spritesVersion;
	private Color line;
	// the client tick the game's sprites were last found incomplete in, when they were first, and when to try next
	private int incompleteCycle = -1;
	private long incompleteSince;
	private long retryAt;

	@Inject
	PickerStyle(SetupPickerConfig config, GameSprites sprites)
	{
		this.config = config;
		this.sprites = sprites;
	}

	/**
	 * Brings the style up to date with the settings and the game's sprites. Call at the start of each render.
	 */
	public void refresh()
	{
		final boolean game = config.matchResourcePack();
		if (game)
		{
			sprites.refresh();
		}
		final boolean current = !game
			|| skin != null && spritesVersion == sprites.getVersion() && line.equals(sprites.getLine())
			|| skin == null && spritesVersion == sprites.getVersion()
			&& (sprites.getCycle() == incompleteCycle || System.currentTimeMillis() < retryAt);
		if (!stale && current)
		{
			return;
		}
		stale = false;

		PickerSkin made = null;
		if (game)
		{
			spritesVersion = sprites.getVersion();
			line = sprites.getLine();
			made = new PickerSkin(sprites);
			if (made.isComplete())
			{
				incompleteSince = 0;
			}
			else
			{
				// in colors meanwhile, which only happens while the cache is still loading them, or if it never has them
				made = null;
				incompleteCycle = sprites.getCycle();
				final long now = System.currentTimeMillis();
				if (incompleteSince == 0)
				{
					incompleteSince = now;
				}
				retryAt = now - incompleteSince < STARTUP_MILLIS ? 0 : now + RETRY_MILLIS;
			}
		}
		else
		{
			// so that turning it on again starts with quick tries
			incompleteSince = 0;
		}
		skin = made;
		theme = made == null
			? new PickerTheme(config.backgroundColor(), config.headerColor(), config.borderColor(), config.accentColor(), config.textColor())
			// the text colors are still the settings' own, worked out against the game's background, and dividing
			// lines are the color of the bank's
			: new PickerTheme(made.getBackground(), made.getField(), line, config.accentColor(), config.textColor());
	}

	public PickerTheme getTheme()
	{
		return theme;
	}

	/**
	 * The game's sprites to draw with, or null to draw in colors.
	 */
	public PickerSkin getSkin()
	{
		return skin;
	}

	/**
	 * How much room the chrome being drawn takes.
	 */
	public PickerLayout.Frame getFrame()
	{
		return skin != null ? PickerLayout.Frame.GAME : PickerLayout.Frame.FLAT;
	}

	/**
	 * Notes a setting that changes the style, of this plugin's or of what reskins the game's interfaces. Safe to
	 * call from any thread.
	 */
	public void onConfigChanged(String group, String key)
	{
		if (SetupPickerConfig.GROUP.equals(group))
		{
			stale = true;
		}
		sprites.onConfigChanged(group, key);
	}

	/**
	 * Notes that every setting may have changed, as on switching profiles.
	 */
	public void invalidate()
	{
		stale = true;
	}
}

package com.setuppicker;

import java.awt.Color;

/**
 * The colors the picker is drawn in. The defaults suit the game's own interfaces; they can be changed in the
 * plugin's settings, for instance to match a resource pack.
 */
public final class PickerTheme
{
	static final Color DEFAULT_BACKGROUND = new Color(40, 34, 26, 240);
	static final Color DEFAULT_HEADER = new Color(62, 53, 41);
	static final Color DEFAULT_BORDER = new Color(87, 80, 64);
	static final Color DEFAULT_ACCENT = new Color(255, 152, 31);
	static final Color DEFAULT_TEXT = new Color(235, 228, 210);

	public static final PickerTheme DEFAULT = new PickerTheme(DEFAULT_BACKGROUND, DEFAULT_HEADER, DEFAULT_BORDER,
		DEFAULT_ACCENT, DEFAULT_TEXT);

	private static final int ACTIVE_ROW_ALPHA = 70;
	private static final double MUTED_TEXT_FADE = 0.45;

	private final Color background;
	private final Color header;
	private final Color border;
	private final Color accent;
	private final Color text;
	private final Color mutedText;
	private final Color activeRow;

	/**
	 * @param accent the title, the keyboard selection, the focused search box and the open setup
	 */
	public PickerTheme(Color background, Color header, Color border, Color accent, Color text)
	{
		this.background = background;
		this.header = header;
		this.border = border;
		this.accent = accent;
		this.text = text;
		// Hints and placeholders: the text color, faded part of the way into the background
		this.mutedText = mix(text, background, MUTED_TEXT_FADE);
		this.activeRow = new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), ACTIVE_ROW_ALPHA);
	}

	private static Color mix(Color from, Color to, double amount)
	{
		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * amount),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * amount),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * amount));
	}

	public Color getBackground()
	{
		return background;
	}

	public Color getHeader()
	{
		return header;
	}

	public Color getBorder()
	{
		return border;
	}

	public Color getAccent()
	{
		return accent;
	}

	public Color getText()
	{
		return text;
	}

	public Color getMutedText()
	{
		return mutedText;
	}

	public Color getActiveRow()
	{
		return activeRow;
	}
}

package com.setuppicker;

import java.awt.event.InputEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.OSType;

/**
 * The "primary" shortcut modifier of the platform being played on: Cmd on a Mac, Ctrl elsewhere.
 *
 * <p>The Platform Keys plugin has a setting to force one platform's keys regardless of the computer. When that
 * plugin hasn't been switched off its choice is followed, so this plugin's shortcut uses the same modifier as its bank search.
 */
@Singleton
public class PlatformModifier
{
	// Platform Keys' config group, its profile setting, and the values that setting takes (its KeyProfile enum)
	private static final String PLATFORM_KEYS_GROUP = "platformkeys";
	private static final String PLATFORM_KEYS_PROFILE = "profile";
	private static final String PROFILE_MAC = "MAC";
	private static final String PROFILE_WINDOWS = "WINDOWS";
	// Where RuneLite records whether the Platform Keys plugin is switched on
	private static final String RUNELITE_GROUP = "runelite";
	private static final String PLATFORM_KEYS_ENABLED = "platformkeysplugin";

	private final ConfigManager configManager;

	@Inject
	PlatformModifier(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * @return {@link InputEvent#META_DOWN_MASK} or {@link InputEvent#CTRL_DOWN_MASK}
	 */
	public int get()
	{
		// plugins count as on until they have been switched off, so there may be no value at all
		final boolean platformKeysEnabled = !"false".equals(configManager.getConfiguration(RUNELITE_GROUP, PLATFORM_KEYS_ENABLED));
		return resolve(platformKeysEnabled ? configManager.getConfiguration(PLATFORM_KEYS_GROUP, PLATFORM_KEYS_PROFILE) : null,
			OSType.getOSType() == OSType.MacOS);
	}

	/**
	 * @param platformKeysProfile Platform Keys' profile setting, or null when that plugin isn't in use
	 */
	static int resolve(String platformKeysProfile, boolean onMac)
	{
		final boolean mac;
		if (PROFILE_MAC.equals(platformKeysProfile))
		{
			mac = true;
		}
		else if (PROFILE_WINDOWS.equals(platformKeysProfile))
		{
			mac = false;
		}
		else
		{
			// no override, or Platform Keys' own auto-detect
			mac = onMac;
		}
		return mac ? InputEvent.META_DOWN_MASK : InputEvent.CTRL_DOWN_MASK;
	}
}

package com.setuppicker;

/**
 * Notices a bank tag being opened, by whatever means, from the open tag changing. Bank Tags doesn't announce
 * it the way Inventory Setups does for its setups. Used from the client thread only.
 */
final class RecentTagTracker
{
	private String previous;

	/**
	 * @param active the bank tag that's open now, or "" for none
	 * @return whether it has just been opened
	 */
	boolean observe(String active)
	{
		final String current = active == null ? "" : active;
		final boolean opened = previous != null && !current.isEmpty() && !current.equals(previous);
		previous = current;
		return opened;
	}

	/**
	 * Forget the open tag, so that the next one seen isn't taken for newly opened: it may just be another
	 * profile's, or one restored on login.
	 */
	void reset()
	{
		previous = null;
	}
}

package com.setuppicker;

import java.awt.Color;

/**
 * One row in the picker: the bits of an inventory setup, or of a bank tag tab, needed to list it.
 */
public final class SetupEntry
{
	// Starts the key of a bank tag. Not something a name can have in it, so a setup and a tag never share a key.
	private static final char BANK_TAG_KEY_PREFIX = '\u0001';

	/**
	 * For a setup that isn't for any spellbook in particular.
	 */
	public static final int NO_SPELLBOOK = -1;

	private final String name;
	private final boolean favorite;
	private final Color displayColor;
	private final int iconItemId;
	private final boolean bankTag;
	private final String notes;
	private final int spellbook;

	public SetupEntry(String name, boolean favorite, Color displayColor, int iconItemId)
	{
		this(name, favorite, displayColor, iconItemId, "");
	}

	/**
	 * @param notes what the user wrote in the setup's notes in Inventory Setups, or "" for nothing
	 */
	public SetupEntry(String name, boolean favorite, Color displayColor, int iconItemId, String notes)
	{
		this(name, favorite, displayColor, iconItemId, notes, NO_SPELLBOOK);
	}

	/**
	 * @param spellbook the spellbook the setup is for, as Inventory Setups numbers them, or {@link #NO_SPELLBOOK}
	 */
	public SetupEntry(String name, boolean favorite, Color displayColor, int iconItemId, String notes, int spellbook)
	{
		this(name, favorite, displayColor, iconItemId, notes, spellbook, false);
	}

	private SetupEntry(String name, boolean favorite, Color displayColor, int iconItemId, String notes, int spellbook,
		boolean bankTag)
	{
		this.spellbook = spellbook;
		this.notes = notes;
		this.name = name;
		this.favorite = favorite;
		this.displayColor = displayColor;
		this.iconItemId = iconItemId;
		this.bankTag = bankTag;
	}

	/**
	 * The entry for a tag tab of the Bank Tags plugin, which has neither a color nor a favorite flag.
	 */
	public static SetupEntry bankTag(String name, int iconItemId)
	{
		return new SetupEntry(name, false, null, iconItemId, "", NO_SPELLBOOK, true);
	}

	/**
	 * The key a bank tag of this name goes by among the recently used.
	 */
	static String bankTagKey(String name)
	{
		return BANK_TAG_KEY_PREFIX + name;
	}

	public String getName()
	{
		return name;
	}

	/**
	 * Whether this is a bank tag tab rather than an inventory setup.
	 */
	public boolean isBankTag()
	{
		return bankTag;
	}

	/**
	 * What tells this entry apart from every other: its name, marked when it's a bank tag's, as a setup and a
	 * tag can be called the same.
	 */
	public String getKey()
	{
		return bankTag ? bankTagKey(name) : name;
	}

	public boolean isFavorite()
	{
		return favorite;
	}

	/**
	 * The color the user gave the setup in Inventory Setups, or null for none.
	 */
	public Color getDisplayColor()
	{
		return displayColor;
	}

	/**
	 * The setup's notes from Inventory Setups, or "" when it has none.
	 */
	public String getNotes()
	{
		return notes;
	}

	/**
	 * The spellbook the setup is for: 0 for standard, 1 ancient, 2 lunar, 3 arceuus, or {@link #NO_SPELLBOOK}.
	 */
	public int getSpellbook()
	{
		return spellbook;
	}

	public int getIconItemId()
	{
		return iconItemId;
	}
}

package com.setuppicker;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A setup's inventory and equipment along with how it has Inventory Setups highlight what differs from what
 * the player has: its "Highlight differences", "Unordered highlighting" and highlight color, and each item's
 * fuzzy and stack compare settings. Works out the slots that its side panel colors in.
 */
final class SetupHighlight
{
	private static final Logger log = LoggerFactory.getLogger(SetupHighlight.class);

	// What Inventory Setups' highlight color starts out as
	static final Color DEFAULT_COLOR = Color.RED;

	/**
	 * How an item's quantity is compared, named as Inventory Setups saves it.
	 */
	enum StackCompare
	{
		None,
		Standard,
		Greater_Than,
		Less_Than;

		static StackCompare parse(String name)
		{
			for (StackCompare value : values())
			{
				if (value.name().equals(name))
				{
					return value;
				}
			}
			return None;
		}

		/**
		 * Whether the quantity alone is enough for the slot to be highlighted.
		 */
		boolean differs(int saved, int current)
		{
			final int compared = Integer.compare(current, saved);
			switch (this)
			{
				case Standard:
					return compared != 0;
				case Greater_Than:
					return compared > 0;
				case Less_Than:
					return compared < 0;
				default:
					return false;
			}
		}
	}

	/**
	 * An item in a slot, of the setup or of the player. An empty slot has an id of -1.
	 */
	static final class Slot
	{
		static final Slot EMPTY = new Slot(-1, 0);

		final int id;
		final int quantity;
		final boolean fuzzy;
		final StackCompare stackCompare;

		Slot(int id, int quantity)
		{
			this(id, quantity, false, StackCompare.None);
		}

		Slot(int id, int quantity, boolean fuzzy, StackCompare stackCompare)
		{
			this.id = id;
			this.quantity = quantity;
			this.fuzzy = fuzzy;
			this.stackCompare = stackCompare;
		}

		boolean isEmpty()
		{
			return id <= 0;
		}
	}

	private final Color color;
	private final boolean unordered;
	private final List<Slot> inventory;
	private final List<Slot> equipment;
	// null for a setup without a rune pouch
	private final List<Slot> runePouch;

	SetupHighlight(Color color, boolean unordered, List<Slot> inventory, List<Slot> equipment)
	{
		this(color, unordered, inventory, equipment, null);
	}

	SetupHighlight(Color color, boolean unordered, List<Slot> inventory, List<Slot> equipment, List<Slot> runePouch)
	{
		this.color = color == null ? DEFAULT_COLOR : color;
		this.unordered = unordered;
		this.inventory = inventory;
		this.equipment = equipment;
		this.runePouch = runePouch;
	}

	/**
	 * Reads a setup's saved json, or returns null when the setup doesn't highlight its differences or can't be
	 * read.
	 */
	static SetupHighlight parse(Gson gson, String json)
	{
		try
		{
			final JsonObject setup = json == null ? null : gson.fromJson(json, JsonObject.class);
			// left out when off
			if (setup == null || !setup.has("hd") || !setup.get("hd").getAsBoolean())
			{
				return null;
			}
			final Color color = setup.has("hc") ? gson.fromJson(setup.get("hc"), Color.class) : null;
			final boolean unordered = setup.has("uh") && setup.get("uh").getAsBoolean();
			// left out for a setup without a rune pouch
			final List<Slot> runePouch = setup.has("rp") && setup.get("rp").isJsonArray() ? slots(setup.getAsJsonArray("rp")) : null;
			return new SetupHighlight(color, unordered, slots(setup.getAsJsonArray("inv")), slots(setup.getAsJsonArray("eq")), runePouch);
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read how a setup is highlighted", e);
			return null;
		}
	}

	private static List<Slot> slots(JsonArray items)
	{
		if (items == null)
		{
			return Collections.emptyList();
		}
		final List<Slot> slots = new ArrayList<>(items.size());
		for (JsonElement element : items)
		{
			// an empty slot is saved as null, or as an item of id -1
			if (element == null || !element.isJsonObject() || !element.getAsJsonObject().has("id"))
			{
				slots.add(Slot.EMPTY);
				continue;
			}
			final JsonObject item = element.getAsJsonObject();
			// each of these is left out when it is the default
			slots.add(new Slot(
				item.get("id").getAsInt(),
				item.has("q") ? item.get("q").getAsInt() : 1,
				item.has("f") && item.get("f").getAsBoolean(),
				item.has("sc") ? StackCompare.parse(item.get("sc").getAsString()) : StackCompare.None));
		}
		return slots;
	}

	Color getColor()
	{
		return color;
	}

	/**
	 * The setup's items whose slots Inventory Setups highlights, given what the player has.
	 *
	 * @param currentInventory  the player's inventory, a slot each
	 * @param currentEquipment  what the player is wearing, by equipment slot
	 * @param currentRunePouch  the runes in the player's rune pouch, or null when they aren't carrying one
	 * @param variation         maps an item to the one id its variants share, for fuzzy items
	 */
	List<Slot> differences(List<Slot> currentInventory, List<Slot> currentEquipment, List<Slot> currentRunePouch,
		IntUnaryOperator variation)
	{
		final List<Slot> differences = new ArrayList<>();
		if (unordered)
		{
			unorderedDifferences(currentInventory, variation, differences);
		}
		else
		{
			orderedDifferences(inventory, currentInventory, variation, differences);
		}
		// Inventory Setups compares equipment slot by slot either way
		orderedDifferences(equipment, currentEquipment, variation, differences);
		if (runePouch != null)
		{
			runePouchDifferences(currentRunePouch, differences);
		}
		return differences;
	}

	/**
	 * Like Inventory Setups, each rune is looked for anywhere in the pouch, and without a pouch all of them are
	 * missing.
	 */
	private void runePouchDifferences(List<Slot> currentRunePouch, List<Slot> differences)
	{
		for (Slot wanted : runePouch)
		{
			if (wanted.isEmpty())
			{
				continue;
			}
			Slot have = null;
			if (currentRunePouch != null)
			{
				for (Slot slot : currentRunePouch)
				{
					if (slot.id == wanted.id)
					{
						have = slot;
						break;
					}
				}
			}
			if (have == null || wanted.stackCompare.differs(wanted.quantity, have.quantity))
			{
				differences.add(wanted);
			}
		}
	}

	private static void orderedDifferences(List<Slot> saved, List<Slot> current, IntUnaryOperator variation, List<Slot> differences)
	{
		for (int i = 0; i < saved.size(); i++)
		{
			final Slot wanted = saved.get(i);
			// a slot that should be empty has nothing in the bank to point at
			if (wanted.isEmpty())
			{
				continue;
			}
			final Slot have = i < current.size() ? current.get(i) : Slot.EMPTY;
			final boolean sameItem = wanted.fuzzy
				? variation.applyAsInt(wanted.id) == variation.applyAsInt(have.id)
				: wanted.id == have.id;
			if (!sameItem || wanted.stackCompare.differs(wanted.quantity, have.quantity))
			{
				differences.add(wanted);
			}
		}
	}

	/**
	 * Each item of the setup's inventory is matched to one anywhere in the player's, exact matches first and
	 * then, for fuzzy items, any variant.
	 */
	private void unorderedDifferences(List<Slot> currentInventory, IntUnaryOperator variation, List<Slot> differences)
	{
		// the quantities of the player's items, a slot each, by item
		final Map<Integer, List<Integer>> current = new HashMap<>();
		for (Slot have : currentInventory)
		{
			if (!have.isEmpty())
			{
				current.computeIfAbsent(have.id, id -> new ArrayList<>()).add(have.quantity);
			}
		}

		// the items that must be exact pick first, then the fuzzy ones take what exact matches are left
		final List<Slot> variants = new ArrayList<>();
		for (boolean fuzzy : new boolean[]{false, true})
		{
			for (Slot wanted : inventory)
			{
				if (wanted.isEmpty() || wanted.fuzzy != fuzzy)
				{
					continue;
				}
				final Integer quantity = take(current.get(wanted.id));
				if (quantity == null && fuzzy)
				{
					variants.add(wanted);
				}
				else if (quantity == null || wanted.stackCompare.differs(wanted.quantity, quantity))
				{
					differences.add(wanted);
				}
			}
		}

		for (Slot wanted : variants)
		{
			Integer quantity = null;
			final int base = variation.applyAsInt(wanted.id);
			for (Map.Entry<Integer, List<Integer>> entry : current.entrySet())
			{
				if (!entry.getValue().isEmpty() && variation.applyAsInt(entry.getKey()) == base)
				{
					quantity = take(entry.getValue());
					break;
				}
			}
			if (quantity == null || wanted.stackCompare.differs(wanted.quantity, quantity))
			{
				differences.add(wanted);
			}
		}
	}

	private static Integer take(List<Integer> quantities)
	{
		return quantities == null || quantities.isEmpty() ? null : quantities.remove(quantities.size() - 1);
	}
}

package com.setuppicker;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.SpritePixels;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The setups' icons at the size the lists draw them. Item sprites are 36x32 and the lists show them at half that.
 * Drawn straight from the sprite, one pixel of every two by two is kept whatever it is, so a thin part such as a
 * staff's shaft or a bow's string is kept where it happens to fall on that pixel and lost where it falls on the
 * outline instead. Each icon is halved once here, still pixel for pixel, but keeping the item's own colours
 * wherever it has any, and then given back the game's outline and shadow at the small size.
 * <p>
 * Client thread only, which is where overlays render and item sprites finish loading.
 */
public class SetupIcons
{
	// The outline and shadow the game draws round an item's sprite, as ItemManager has it draw them
	private static final int OUTLINE = 0xff000001;
	private static final int SHADOW = 0xff000000 | SpritePixels.DEFAULT_SHADOW_COLOR;

	private final ItemManager itemManager;
	private final Map<Integer, BufferedImage> icons = new HashMap<>();

	SetupIcons(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * The icon of an item at the lists' size, or null when there is none. Until the item's sprite has loaded,
	 * the sprite itself.
	 */
	public BufferedImage get(int itemId)
	{
		final BufferedImage icon = icons.get(itemId);
		if (icon != null)
		{
			return icon;
		}
		final AsyncBufferedImage sprite = itemManager.getImage(itemId);
		if (sprite == null)
		{
			return null;
		}
		// in the meantime the sprite stands in for it, so that it is only asked for once
		icons.put(itemId, sprite);
		sprite.onLoaded(() -> icons.put(itemId, halve(sprite)));
		return sprite;
	}

	/**
	 * Halves an item sprite without blending: each pixel of the result is one of the two by two it stands for.
	 * Of those it is the item's most vivid one, so that thin coloured parts survive, and only where there is none
	 * of the item is it left empty. The outline and shadow are then drawn round the result as the game draws them
	 * round a sprite, a pixel wide at the new size.
	 * <p>
	 * The item can reach the sprite's edge once halved, so the result has a pixel's margin all round for its outline
	 * and shadow: it is two pixels wider and taller than half the sprite, with the halved sprite in the middle.
	 */
	static BufferedImage halve(BufferedImage sprite)
	{
		final int width = sprite.getWidth() / 2 + 2;
		final int height = sprite.getHeight() / 2 + 2;
		final int[] source = sprite.getRGB(0, 0, sprite.getWidth(), sprite.getHeight(), null, 0, sprite.getWidth());
		final int[] item = new int[width * height];
		for (int y = 1; y < height - 1; y++)
		{
			for (int x = 1; x < width - 1; x++)
			{
				int best = 0;
				for (int dy = 0; dy < 2; dy++)
				{
					for (int dx = 0; dx < 2; dx++)
					{
						final int pixel = source[(2 * (y - 1) + dy) * sprite.getWidth() + 2 * (x - 1) + dx];
						if (isItem(pixel) && (best == 0 || vividness(pixel) > vividness(best)))
						{
							best = pixel;
						}
					}
				}
				item[y * width + x] = best;
			}
		}

		// the outline round the item, then the shadow down and to the right of both, as SpritePixels draws them
		final int[] outlined = item.clone();
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if (item[y * width + x] == 0 && (x > 0 && item[y * width + x - 1] != 0 || x < width - 1 && item[y * width + x + 1] != 0
					|| y > 0 && item[(y - 1) * width + x] != 0 || y < height - 1 && item[(y + 1) * width + x] != 0))
				{
					outlined[y * width + x] = OUTLINE;
				}
			}
		}
		final int[] shadowed = outlined.clone();
		for (int y = 1; y < height; y++)
		{
			for (int x = 1; x < width; x++)
			{
				if (outlined[y * width + x] == 0 && outlined[(y - 1) * width + x - 1] != 0)
				{
					shadowed[y * width + x] = SHADOW;
				}
			}
		}
		final BufferedImage halved = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		halved.setRGB(0, 0, width, height, shadowed, 0, width);
		return halved;
	}

	/**
	 * Whether a pixel is part of the item itself, not its outline, its shadow or nothing.
	 */
	private static boolean isItem(int pixel)
	{
		return pixel >>> 24 != 0 && pixel != OUTLINE && (pixel | 0xff000000) != SHADOW;
	}

	/**
	 * How strongly coloured a pixel is, with brightness to choose between greys: what makes a pixel stand out as
	 * the detail of a small picture.
	 */
	private static int vividness(int pixel)
	{
		final int red = pixel >> 16 & 0xff;
		final int green = pixel >> 8 & 0xff;
		final int blue = pixel & 0xff;
		final int max = Math.max(red, Math.max(green, blue));
		final int min = Math.min(red, Math.min(green, blue));
		return (max - min) * 4 + max;
	}
}

package com.setuppicker;

/**
 * Decides whether a name matches what has been typed in the search box.
 *
 * <p>There are three ways to match, from strict to loose. The search uses the strictest one that finds
 * anything, so the looser ones only come into play when a search would otherwise come up empty.
 */
public final class SetupMatcher
{
	public enum Tier
	{
		/**
		 * The name contains the search text.
		 */
		EXACT,
		/**
		 * The name contains the search text give or take a slip: a wrong, missing or extra letter, or two
		 * letters swapped.
		 */
		TYPO,
		/**
		 * The name contains the search text's letters in order, with anything in between ("vkdh" for
		 * "Vorkath (dhcb)").
		 */
		SUBSEQUENCE
	}

	// Short searches are too easy to match by accident to allow slips in
	private static final int MIN_LENGTH_FOR_TYPO = 4;
	private static final int MIN_LENGTH_FOR_TWO_TYPOS = 8;
	private static final int MIN_LENGTH_FOR_SUBSEQUENCE = 3;

	private SetupMatcher()
	{
	}

	/**
	 * @param name   lower case
	 * @param needle the search text, lower case and not empty
	 */
	public static boolean matches(String name, String needle, Tier tier)
	{
		switch (tier)
		{
			case EXACT:
				return name.contains(needle);
			case TYPO:
				if (needle.length() < MIN_LENGTH_FOR_TYPO)
				{
					return false;
				}
				return closestSubstringDistance(name, needle) <= (needle.length() < MIN_LENGTH_FOR_TWO_TYPOS ? 1 : 2);
			default:
				return needle.length() >= MIN_LENGTH_FOR_SUBSEQUENCE && isSubsequence(name, needle);
		}
	}

	private static boolean isSubsequence(String name, String needle)
	{
		int matched = 0;
		for (int i = 0; i < name.length() && matched < needle.length(); i++)
		{
			if (name.charAt(i) == needle.charAt(matched))
			{
				matched++;
			}
		}
		return matched == needle.length();
	}

	/**
	 * The fewest single-letter edits (replace, insert, delete, or swap two neighbours) that turn the needle
	 * into some stretch of the name.
	 */
	static int closestSubstringDistance(String name, String needle)
	{
		final int n = needle.length();
		final int m = name.length();
		// distance[i][j]: the first i letters of the needle against the closest stretch of the name ending at j
		final int[][] distance = new int[n + 1][m + 1];
		for (int i = 1; i <= n; i++)
		{
			distance[i][0] = i;
		}
		// row 0 stays 0: a match may start anywhere in the name for free
		for (int i = 1; i <= n; i++)
		{
			for (int j = 1; j <= m; j++)
			{
				final int replace = needle.charAt(i - 1) == name.charAt(j - 1) ? 0 : 1;
				int best = Math.min(distance[i - 1][j - 1] + replace,
					Math.min(distance[i - 1][j] + 1, distance[i][j - 1] + 1));
				if (i > 1 && j > 1 && needle.charAt(i - 1) == name.charAt(j - 2) && needle.charAt(i - 2) == name.charAt(j - 1))
				{
					best = Math.min(best, distance[i - 2][j - 2] + 1);
				}
				distance[i][j] = best;
			}
		}
		int closest = n;
		for (int j = 0; j <= m; j++)
		{
			closest = Math.min(closest, distance[n][j]);
		}
		return closest;
	}
}

